const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const STORAGE_KEY='lynq-agency-crm-v7';
const LEGACY_STORAGE_KEY='lynq-agency-crm-v6';
const DEMO_CLEANUP_KEY='lynq-agency-demo-cleanup-v1';

const THEME_KEY='lynq-agency-theme-v1';
const SUBTHEME_KEY='lynq-agency-subtheme-v1';
const DEFAULT_ACCENT='#6B1730';
const DEFAULT_SUB_ACCENT='#D9BDA9';
const NOTIFICATION_SETTINGS_KEY='lynq-agency-notifications-v1';
