const DEFAULT_NOTIFICATION_SETTINGS={emailEnabled:true,email:'sheling@shelingcynthia.nl',events:{trajectory_paused:true,trajectory_resumed:true,trajectory_ended:true,payment_overdue:true,trajectory_ending:true,content_attention:true}};
function loadNotificationSettings(){try{const saved=JSON.parse(localStorage.getItem(NOTIFICATION_SETTINGS_KEY)||'null')||{};return{...structuredClone(DEFAULT_NOTIFICATION_SETTINGS),...saved,events:{...DEFAULT_NOTIFICATION_SETTINGS.events,...(saved.events||{})}}}catch{return structuredClone(DEFAULT_NOTIFICATION_SETTINGS)}}
function saveNotificationSettings(settings){localStorage.setItem(NOTIFICATION_SETTINGS_KEY,JSON.stringify(settings))}
function notificationLog(){try{return JSON.parse(localStorage.getItem(NOTIFICATION_LOG_KEY)||'[]')}catch{return[]}}
function saveNotificationLog(log){localStorage.setItem(NOTIFICATION_LOG_KEY,JSON.stringify(log.slice(0,80)))}
function notificationTypeLabel(type){return({trajectory_paused:'Traject gepauzeerd',trajectory_resumed:'Traject hervat',trajectory_ended:'Traject beëindigd',payment_overdue:'Betaling achterstallig',trajectory_ending:'Traject loopt af',content_attention:'Content vraagt aandacht'})[type]||type}
function notificationStatusLabel(status){return status==='sent'?'Verzonden':status==='failed'?'Mislukt':status==='waiting_backend'?'Wacht op backend':'Geregistreerd'}
function updateNotificationSetting(key,value){const s=loadNotificationSettings();if(key==='emailEnabled')s.emailEnabled=!!value;else if(key==='email')s.email=String(value||'').trim();else if(key.startsWith('event:'))s.events[key.slice(6)]=!!value;saveNotificationSettings(s);render()}
function notificationRecipientValid(){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(loadNotificationSettings().email||'')}
async function queueNotificationEvent(type,payload={},eventKey=''){const settings=loadNotificationSettings();if(!settings.emailEnabled||!settings.events[type]||!notificationRecipientValid())return false;const log=notificationLog();if(eventKey&&log.some(x=>x.eventKey===eventKey))return false;const endpoint=localStorage.getItem(NOTIFICATION_API_URL_KEY)||'';const entry={id:uid('notif'),type,eventKey:eventKey||'',createdAt:new Date().toISOString(),recipient:settings.email,status:endpoint?'queued':'waiting_backend',payload,workspace:state.workspace};log.unshift(entry);saveNotificationLog(log);if(!endpoint)return true;try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({channel:'email',recipient:settings.email,type,timestamp:entry.createdAt,workspace:state.workspace,payload,source:'lynq-sheling-crm'})});entry.status=response.ok?'sent':'failed'}catch{entry.status='failed'}saveNotificationLog(log);return entry.status==='sent'}
function clearNotificationLog(){if(!confirm('Notificatielog leegmaken?'))return;saveNotificationLog([]);render()}
function scanImportantNotifications(){const today=new Date().toISOString().slice(0,10),month=today.slice(0,7);(data.sheling?.clients||[]).forEach(c=>{(c.installments||[]).filter(i=>i.status!=='paid'&&daysUntil(i.due)<0).forEach(i=>queueNotificationEvent('payment_overdue',{clientId:c.id,clientName:c.contact||c.company,amount:Number(i.amount||0),due:i.due},`payment_overdue:${c.id}:${i.id}:${i.due}`));const d=daysUntil(c.end);if(c.end&&d>=0&&d<=30)queueNotificationEvent('trajectory_ending',{clientId:c.id,clientName:c.contact||c.company,endDate:c.end,daysRemaining:d},`trajectory_ending:${c.id}:${c.end}`)});(data.lynq?.clients||[]).forEach(c=>{try{const prev=state.workspace;state.workspace='lynq';const h=contentHealth(c);state.workspace=prev;if(h.behind)queueNotificationEvent('content_attention',{clientId:c.id,clientName:c.company,status:h.status,done:h.done,total:h.total},`content_attention:${c.id}:${month}`)}catch{}})}
function validHex(v){return /^#[0-9A-F]{6}$/i.test(String(v||'').trim())}
function hexRgb(hex){const h=hex.replace('#','');return [parseInt(h.slice(0,2),16),parseInt(h.slice(2,4),16),parseInt(h.slice(4,6),16)]}
function mixHex(hex,white=.9){const [r,g,b]=hexRgb(hex),m=x=>Math.round(x+(255-x)*white).toString(16).padStart(2,'0');return '#'+m(r)+m(g)+m(b)}
function applyBrandColor(hex,save=true){hex=String(hex||'').trim().toUpperCase();if(!validHex(hex))return false;const root=document.documentElement;root.style.setProperty('--wine',hex);root.style.setProperty('--wine-2',mixHex(hex,.08));root.style.setProperty('--wine-3',hex);root.style.setProperty('--accent-soft',mixHex(hex,.9));const [r,g,b]=hexRgb(hex);root.style.setProperty('--accent-ring',`rgba(${r},${g},${b},.13)`);document.querySelector('meta[name="theme-color"]')?.setAttribute('content',hex);if(save)localStorage.setItem(THEME_KEY,hex);return true}
function applySubColor(hex,save=true){hex=String(hex||'').trim().toUpperCase();if(!validHex(hex))return false;const root=document.documentElement;root.style.setProperty('--sub-accent',hex);root.style.setProperty('--sub-accent-soft',mixHex(hex,.86));if(save)localStorage.setItem(SUBTHEME_KEY,hex);return true}
function loadBrandColor(){applyBrandColor(localStorage.getItem(THEME_KEY)||DEFAULT_ACCENT,false);applySubColor(localStorage.getItem(SUBTHEME_KEY)||DEFAULT_SUB_ACCENT,false)}
function setSubColor(value){const v=String(value||'').trim();if(!validHex(v)){toast('Gebruik een geldige HEX-kleur');return}applySubColor(v,true);const input=$('#subBrandHex'),picker=$('#subBrandPicker');if(input)input.value=v.toUpperCase();if(picker)picker.value=v;toast('Subkleur aangepast')}
function resetBrandStudio(){applyBrandColor(DEFAULT_ACCENT,true);applySubColor(DEFAULT_SUB_ACCENT,true);render();toast('Huisstijl hersteld')}
function rgbToHsl(r,g,b){r/=255;g/=255;b/=255;const max=Math.max(r,g,b),min=Math.min(r,g,b);let h=0,s=0,l=(max+min)/2;if(max!==min){const d=max-min;s=l>.5?d/(2-max-min):d/(max+min);switch(max){case r:h=(g-b)/d+(g<b?6:0);break;case g:h=(b-r)/d+2;break;default:h=(r-g)/d+4}h*=60}return[h,s*100,l*100]}
function hslToHex(h,s,l){s/=100;l/=100;const k=n=>(n+h/30)%12,a=s*Math.min(l,1-l),f=n=>l-a*Math.max(-1,Math.min(k(n)-3,Math.min(9-k(n),1)));return '#'+[f(0),f(8),f(4)].map(x=>Math.round(255*x).toString(16).padStart(2,'0')).join('').toUpperCase()}
function hueOf(hex){if(!validHex(hex))return 0;return Math.round(rgbToHsl(...hexRgb(hex))[0])}
function setHue(kind,h){const key=kind==='sub'?SUBTHEME_KEY:THEME_KEY,def=kind==='sub'?DEFAULT_SUB_ACCENT:DEFAULT_ACCENT,current=localStorage.getItem(key)||def,[,sat,light]=rgbToHsl(...hexRgb(current)),hex=hslToHex(Number(h),sat,light);if(kind==='sub'){applySubColor(hex,false);$('#subBrandHex').value=hex;$('#subBrandPicker').value=hex}else{applyBrandColor(hex,false);$('#brandHex').value=hex;$('#brandPicker').value=hex}updateBrandPreview()}
function updateBrandPreview(){const primary=$('#brandHex')?.value||localStorage.getItem(THEME_KEY)||DEFAULT_ACCENT,sub=$('#subBrandHex')?.value||localStorage.getItem(SUBTHEME_KEY)||DEFAULT_SUB_ACCENT;document.querySelectorAll('[data-preview-primary]').forEach(el=>el.style.background=primary);document.querySelectorAll('[data-preview-primary-text]').forEach(el=>el.style.color=primary);document.querySelectorAll('[data-preview-sub]').forEach(el=>el.style.background=sub)}
function setBrandColor(value){const v=String(value||'').trim();if(!validHex(v)){toast('Gebruik een geldige HEX-kleur, bijvoorbeeld #6B1730');return}applyBrandColor(v,true);const input=$('#brandHex'),picker=$('#brandPicker');if(input)input.value=v.toUpperCase();if(picker)picker.value=v;toast('Huisstijlkleur aangepast')}
function resetBrandColor(){applyBrandColor(DEFAULT_ACCENT,true);const input=$('#brandHex'),picker=$('#brandPicker');if(input)input.value=DEFAULT_ACCENT;if(picker)picker.value=DEFAULT_ACCENT;toast('Bordeaux huisstijl hersteld')}

