let state={workspace:'lynq',page:'dashboard',clientId:null,tab:'overview',taskFilter:'open',contentFilter:'all',settingsTab:'brand',financeFilter:'open',contentView:'list',contentMonth:new Date().toISOString().slice(0,7)};
function stripDemoClients(source){
  if(!source||typeof source!=='object')return source;
  const clone=structuredClone(source);
  const demoIds={lynq:new Set(['l1','l2','l3']),sheling:new Set(['s1','s2','s3'])};
  const demoEmails=new Set(['noa@ateliernoe.nl','hello@studionomi.nl','june@houseofjune.nl','lisa@example.nl','emma@example.nl','sofia@example.nl']);
  for(const key of ['lynq','sheling']){
    if(!clone[key])continue;
    clone[key].clients=(clone[key].clients||[]).filter(c=>!demoIds[key].has(c.id)&&!demoEmails.has(String(c.email||'').toLowerCase()));
  }
  return clone;
}
function loadData(){
  try{
    const current=localStorage.getItem(STORAGE_KEY);
    if(current)return stripDemoClients(JSON.parse(current));
    const legacy=localStorage.getItem(LEGACY_STORAGE_KEY);
    if(legacy){const migrated=stripDemoClients(JSON.parse(legacy));localStorage.setItem(STORAGE_KEY,JSON.stringify(migrated));return migrated}
    return structuredClone(defaultData);
  }catch{return structuredClone(defaultData)}
}
function saveData(msg='Opgeslagen'){localStorage.setItem(STORAGE_KEY,JSON.stringify(data));const el=$('#saveStatus');if(el)el.textContent=`${msg} · ${new Date().toLocaleDateString('nl-NL')} ${new Date().toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit'})}`}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function uid(prefix='id'){return prefix+Math.random().toString(36).slice(2,9)}
function money(n){return new Intl.NumberFormat('nl-NL',{style:'currency',currency:'EUR',minimumFractionDigits:0,maximumFractionDigits:2}).format(Number(n)||0)}
function fmtDate(v){if(!v)return '—';const d=new Date(v+'T12:00:00');return d.toLocaleDateString('nl-NL',{day:'numeric',month:'short',year:'numeric'})}
function initials(v=''){return v.split(/\s+/).filter(Boolean).map(x=>x[0]).slice(0,2).join('').toUpperCase()||'KL'}
function workspace(){return data[state.workspace]}
function serviceById(id){return workspace().services.find(s=>s.id===id)}
function activeLink(c){return (c.serviceLinks||[]).find(x=>x.status==='active')||(c.serviceLinks||[])[0]}
function postsFor(c){const s=serviceById(activeLink(c)?.serviceId);return Number(c.postsPerMonth||s?.posts||0)}
function icon(name){const icons={dashboard:'<path d="M3 10.8 12 3l9 7.8v9.2a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/>',clients:'<circle cx="9" cy="8" r="3"/><path d="M3.7 19c.5-3.2 2.4-5 5.3-5s4.8 1.8 5.3 5M16 5.5a3 3 0 0 1 0 5.8M17 14c2.2.5 3.4 2.1 3.8 4.5"/>',services:'<path d="M4 7.5 12 3l8 4.5v9L12 21l-8-4.5z"/><path d="m4 7.5 8 4.5 8-4.5M12 12v9"/>',tasks:'<rect x="4" y="4" width="16" height="16" rx="3"/><path d="m8 12 2.5 2.5L16 9"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 9h18"/>',files:'<path d="M5 3h9l5 5v13H5z"/><path d="M14 3v5h5M8 13h8M8 17h6"/>',finance:'<rect x="4" y="5" width="16" height="14" rx="2"/><path d="M4 9h16M8 14h4"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2.8 2.8-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.6v.2h-4V21a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1L4.2 17l.1-.1a1.7 1.7 0 0 0 .3-1.9A1.7 1.7 0 0 0 3 14H2.8v-4H3a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9L4.2 7 7 4.2l.1.1a1.7 1.7 0 0 0 1.9.3A1.7 1.7 0 0 0 10 3V2.8h4V3a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.1-.1L19.8 7l-.1.1a1.7 1.7 0 0 0-.3 1.9A1.7 1.7 0 0 0 21 10h.2v4H21a1.7 1.7 0 0 0-1.6 1z"/>',content:'<rect x="4" y="4" width="16" height="16" rx="2"/><path d="M8 4v16M8 10h12"/>',installments:'<rect x="3" y="6" width="18" height="13" rx="2"/><path d="M3 10h18M7 15h4"/>'};return `<svg viewBox="0 0 24 24">${icons[name]||icons.services}</svg>`}
const navs={lynq:[['dashboard','dashboard','Vandaag'],['clients','clients','Klanten'],['services','services','Pakketten'],['content','content','Contentplanning'],['proposals','files','Voorstellen'],['tasks','tasks','Taken'],['files','files','Bestanden'],['finance','finance','Financieel'],['settings','settings','Instellingen']],sheling:[['dashboard','dashboard','Vandaag'],['clients','clients','Klanten'],['services','services','Trajecten'],['installments','installments','Termijnbetalingen'],['tasks','tasks','Taken'],['files','files','Bestanden'],['settings','settings','Instellingen']]};
function renderNav(){document.body.classList.toggle('workspace-sheling',state.workspace==='sheling');const items=navs[state.workspace];$('#nav').innerHTML=items.map(([p,i,l])=>`<button class="navitem ${state.page===p||state.page==='client'&&p==='clients'?'active wine-active':''}" data-page="${p}"><span class="navicon">${icon(i)}</span><span>${l}</span></button>`).join('');$$('.navitem').forEach(b=>b.onclick=()=>go(b.dataset.page));$('#workspaceLabel').textContent=state.workspace==='lynq'?'LYNQ Agency':'ShelingCynthia';$('#brandMain').textContent=state.workspace==='lynq'?'LYNQ Agency':'SHELINGCYNTHIA';$('#brandSub').textContent='';$('#brandMain').dataset.brand=state.workspace==='lynq'?'lynq':'sheling'}
function go(page){state.page=page;state.clientId=null;state.tab='overview';render();renderNav();if(innerWidth<850)$('#sidebar').classList.remove('open')}
function pageHead(title,sub,actions=''){return `<div class="page-head"><div><h1 class="page-title">${title}</h1><div class="page-sub">${sub}</div></div><div class="head-actions">${actions}</div></div>`}
function dashboard(){
  const clients=workspace().clients, active=clients.filter(c=>['Actief','Onboarding'].includes(c.status)).length;
  const openTasks=allTasks('open'), notices=notifications();
  const todayLabel=new Intl.DateTimeFormat('nl-NL',{weekday:'long',day:'numeric',month:'long'}).format(new Date());
  let body='';
  if(state.workspace==='lynq'){
    const mrr=clients.reduce((sum,c)=>{const l=activeLink(c),svc=serviceById(l?.serviceId);return sum+(svc?.billing==='monthly'&&l?.status==='active'?Number(l.rate||svc.price):0)},0);
    const total=clients.reduce((a,c)=>a+postsFor(c),0),done=clients.reduce((a,c)=>a+Number(c.postsDone||0),0),remaining=Math.max(0,total-done);
    const attention=notices.filter(n=>n.priority!=='info');
    body=`
      <section class="dashboard-hero-band">
        <div class="hero-band-copy">
          <span class="hero-band-date">${todayLabel}</span>
          <h2>Goedemiddag, Sheling.</h2>
          <p>Hier zie je alleen wat vandaag of binnenkort aandacht nodig heeft.</p>
        </div>
        <div class="hero-band-actions">
          <button class="primary hero-band-btn" onclick="openNewClient()">+ Nieuwe klant</button>
        </div>
      </section>
      <div class="focus-kpis">
        ${focusMetric('Actieve klanten',active,`${clients.length} totaal`,'clients')}
        ${focusMetric('Posts open',remaining,`${done} van ${total} online`,'content')}
        ${focusMetric('Omzet p/m',money(mrr),'lopende pakketten','finance')}
        ${focusMetric('Aandacht nodig',attention.length,attention.length?'open signalen':'alles op schema','dashboard')}
      </div>
      <div class="focus-dashboard-grid">
        <section class="section-card focus-attention">
          <div class="section-head">
            <div><strong>Aandacht nodig</strong><small>Alleen uitzonderingen en deadlines</small></div>
            <span class="notice-pill">${attention.length}</span>
          </div>
          <div class="attention-list">${attention.slice(0,8).map(notificationRow).join('')||'<div class="empty-state-v9">Geen urgente aandachtspunten. Alles loopt op schema.</div>'}</div>
        </section>
        <aside class="section-card focus-today">
          <div class="section-head">
            <div><strong>Vandaag & deze week</strong><small>Open acties op volgorde</small></div>
            <button class="ghost" onclick="go('tasks')">Alle taken →</button>
          </div>
          <div class="v9-task-list">${openTasks.slice(0,6).map(t=>taskRowMini(t)).join('')||'<div class="empty-state-v9">Geen open taken.</div>'}</div>
        </aside>
      </div>
      <section class="section-card focus-secondary content-overview-section">
        <div class="section-head">
          <div><strong>Content per klant</strong><small>Zie direct wie op schema ligt en waar nog werk openstaat.</small></div>
          <button class="ghost" onclick="go('clients')">Bekijk klanten →</button>
        </div>
        <div class="content-dashboard-grid">${clients.filter(c=>postsFor(c)>0).slice(0,6).map(c=>contentClientCard(c,true)).join('')||'<div class="empty-state-v9">Nog geen klanten met contentafspraken.</div>'}</div>
      </section>`;
  }else{
    const openInst=allInstallments().filter(x=>x.status!=='paid'), overdue=openInst.filter(x=>x.effectiveStatus==='overdue');
    const ending=clients.filter(c=>{const d=daysUntil(c.end);return d>=0&&d<=30}).length;
    const resumes=clients.filter(c=>c.status==='Gepauzeerd'&&daysUntil(c.resume)>=0&&daysUntil(c.resume)<=30).length;
    const attention=notices.filter(n=>n.priority!=='info');
    body=`
      <section class="dashboard-hero-band">
        <div class="hero-band-copy">
          <span class="hero-band-date">${todayLabel}</span>
          <h2>Goedemiddag, Sheling.</h2>
          <p>Trajecten, hervatmomenten en betalingen die nu aandacht vragen.</p>
        </div>
        <div class="hero-band-actions">
          <button class="primary hero-band-btn" onclick="openNewClient()">+ Nieuwe klant</button>
        </div>
      </section>
      <div class="focus-kpis">
        ${focusMetric('Actieve trajecten',active,`${clients.length} totaal`,'clients')}
        ${focusMetric('Eindigen binnenkort',ending,'binnen 30 dagen','clients')}
        ${focusMetric('Open termijnen',openInst.length,overdue.length?`${overdue.length} achterstallig`:'geen achterstand','installments')}
        ${focusMetric('Hervatten binnenkort',resumes,'binnen 30 dagen','clients')}
      </div>
      <div class="focus-dashboard-grid">
        <section class="section-card focus-attention">
          <div class="section-head">
            <div><strong>Aandacht nodig</strong><small>Trajecten, hervattingen en betalingen</small></div>
            <span class="notice-pill">${attention.length}</span>
          </div>
          <div class="attention-list">${attention.slice(0,8).map(notificationRow).join('')||'<div class="empty-state-v9">Geen urgente aandachtspunten.</div>'}</div>
        </section>
        <aside class="section-card focus-today">
          <div class="section-head">
            <div><strong>Vandaag & deze week</strong><small>Open acties</small></div>
            <button class="ghost" onclick="go('tasks')">Alle taken →</button>
          </div>
          <div class="v9-task-list">${openTasks.slice(0,6).map(t=>taskRowMini(t)).join('')||'<div class="empty-state-v9">Geen open taken.</div>'}</div>
        </aside>
      </div>
      <section class="section-card focus-secondary">
        <div class="section-head">
          <div><strong>Komende betalingen</strong><small>De eerstvolgende open termijnen</small></div>
          <button class="ghost" onclick="go('installments')">Open betalingen →</button>
        </div>
        <div class="payment-mini-list">${openInst.sort((a,b)=>a.i.due.localeCompare(b.i.due)).slice(0,5).map(x=>paymentMiniRow(x)).join('')||'<div class="empty-state-v9">Geen open termijnen.</div>'}</div>
      </section>`;
  }
  return `<div class="page dashboard-page">${body}</div>`
}
function focusMetric(label,value,sub,page){return `<button class="focus-kpi" onclick="go('${page}')"><span>${label}</span><strong>${value}</strong><small>${sub}</small></button>`}
function notificationRow(n){return `<button class="attention-row ${n.priority||'info'}" onclick="${n.clientId?`openClient('${n.clientId}')`:`go('${n.page||'dashboard'}')`}"><span class="attention-mark"></span><div><strong>${esc(n.title)}</strong><small>${esc(n.sub||'')}</small></div><b>${n.priority==='urgent'?'Urgent':n.priority==='attention'?'Aandacht':'Info'}</b><i>→</i></button>`}
function allInstallments(){return data.sheling.clients.flatMap(c=>(c.installments||[]).map(i=>{const d=daysUntil(i.due);return {c,i,status:i.status,effectiveStatus:i.status==='paid'?'paid':d<0?'overdue':d===0?'today':'open'}}))}
function paymentMiniRow(x){return `<button class="payment-mini" onclick="openClient('${x.c.id}')"><div><strong>${esc(x.c.contact)}</strong><small>Termijn ${x.i.nr} · ${fmtDate(x.i.due)}</small></div><span>${money(x.i.amount)}</span><b class="${x.effectiveStatus}">${x.effectiveStatus==='overdue'?'Achterstallig':x.effectiveStatus==='today'?'Vandaag':'Open'}</b></button>`}
function metricCard(iconName,label,value,foot,action,page){return `<button class="kpi premium-kpi" onclick="go('${page}')"><div class="kpi-top"><span class="kpi-icon">${icon(iconName)}</span><span class="kpi-arrow">↗</span></div><div class="kpi-label">${label}</div><div class="kpi-value">${value}</div><div class="kpi-foot"><span>${foot}</span><b>${action}</b></div></button>`}
function contentHealth(c){const total=postsFor(c),done=Number(c.postsDone||0),open=Math.max(0,total-done);const now=new Date('2026-09-02T12:00:00'),daysInMonth=new Date(now.getFullYear(),now.getMonth()+1,0).getDate(),expected=total?Math.round(total*(now.getDate()/daysInMonth)):0,complete=total>0&&done>=total,behind=!complete&&total>0&&done+1<expected;return{total,done,open,pct:total?Math.min(100,Math.round(done/total*100)):0,complete,behind,status:complete?'Voltooid':behind?'Aandacht':'Op schema'}}
function contentClientCard(c,compact=false){const h=contentHealth(c),svc=serviceById(activeLink(c)?.serviceId);return `<button class="content-client-card ${compact?'compact':''}" onclick="openClient('${c.id}')"><div class="content-card-head"><span class="content-client-avatar">${initials(c.company)}</span><span class="content-client-title"><strong>${esc(c.company)}</strong><small>${esc(svc?.name||'Geen pakket')} · start ${fmtDate(c.start)}</small></span><span class="content-health ${h.complete?'complete':h.behind?'behind':'ontrack'}">${h.status}</span></div><div class="content-numbers"><div><small>Online</small><strong>${h.done}</strong></div><span class="content-divider"></span><div><small>Afgesproken</small><strong>${h.total}</strong></div><span class="content-divider"></span><div><small>Nog open</small><strong>${h.open}</strong></div></div><div class="content-card-progress"><i style="width:${h.pct}%"></i></div><div class="content-card-foot"><span>${h.pct}% afgerond</span><b>${h.done} / ${h.total} posts</b></div></button>`}


function clients(){const services=workspace().services;const isL=state.workspace==='lynq';return `<div class="page">${pageHead('Klanten',isL?'Filter snel op status, pakket, startdatum, content en aandachtspunten.':'Filter op trajectstatus, einddatum, hervatmoment en betalingen.','<button class="outline" onclick="openClientImport()">Klanten importeren</button><button class="primary wine-btn" onclick="openNewClient()">+ Nieuwe klant</button>')}<div class="saved-filters"><button class="saved-filter active" data-quick="all">Alle klanten</button><button class="saved-filter" data-quick="active">Actief</button><button class="saved-filter" data-quick="attention">Aandacht nodig</button>${isL?'<button class="saved-filter" data-quick="content">Content open</button><button class="saved-filter" data-quick="ending">Loopt bijna af</button>':'<button class="saved-filter" data-quick="ending">Loopt bijna af</button><button class="saved-filter" data-quick="paused">Gepauzeerd</button><button class="saved-filter" data-quick="payment">Open betaling</button>'}</div><div class="filters client-filter-grid"><div class="field-inline search-wide"><label>Zoeken</label><input id="clientSearch" placeholder="Naam, bedrijf of e-mail"></div><div class="field-inline"><label>Status</label><select id="clientStatus"><option value="">Alle statussen</option>${[...new Set(workspace().clients.map(c=>c.status))].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field-inline"><label>${isL?'Pakket':'Traject'}</label><select id="clientService"><option value="">Alle ${isL?'pakketten':'trajecten'}</option>${services.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><div class="field-inline"><label>Start vanaf</label><input id="clientStart" type="date"></div><div class="field-inline"><label>${isL?'Einddatum':'Eindigt binnen'}</label>${isL?'<input id="clientEnd" type="date">':'<select id="clientEnding"><option value="">Alle</option><option value="7">7 dagen</option><option value="14">14 dagen</option><option value="30">30 dagen</option></select>'}</div>${isL?'<div class="field-inline"><label>Posts p/m</label><select id="clientPosts"><option value="">Alle</option><option value="8">8</option><option value="12">12</option><option value="20">20</option></select></div>':'<div class="field-inline"><label>Betaling</label><select id="clientPayment"><option value="">Alle</option><option value="open">Openstaand</option><option value="overdue">Achterstallig</option><option value="paid">Betaald</option></select></div>'}</div><div id="clientTable"></div></div>`}
function renderClientTable(){if(!$('#clientTable'))return;const isL=state.workspace==='lynq',q=($('#clientSearch')?.value||'').toLowerCase(),status=$('#clientStatus')?.value||'',svc=$('#clientService')?.value||'',start=$('#clientStart')?.value||'',end=$('#clientEnd')?.value||'',ending=Number($('#clientEnding')?.value||0),posts=Number($('#clientPosts')?.value||0),pay=$('#clientPayment')?.value||'',quick=document.querySelector('.saved-filter.active')?.dataset.quick||'all';const hasAttention=c=>(isL?lynqAttention(c):notifications().filter(n=>n.clientId===c.id&&n.priority!=='info')).length>0;const list=workspace().clients.filter(c=>{const matchQ=!q||c.company.toLowerCase().includes(q)||c.contact.toLowerCase().includes(q)||c.email.toLowerCase().includes(q);if(!matchQ||status&&c.status!==status||svc&&!(c.serviceLinks||[]).some(l=>l.serviceId===svc&&l.status==='active')||start&&c.start<start||end&&c.end!==end||posts&&postsFor(c)!==posts)return false;if(ending&&!(daysUntil(c.end)>=0&&daysUntil(c.end)<=ending))return false;if(pay){const ps=(c.installments||[]).map(i=>i.status==='paid'?'paid':daysUntil(i.due)<0?'overdue':'open');if(!ps.includes(pay))return false}if(quick==='active'&&!['Actief','Onboarding'].includes(c.status))return false;if(quick==='attention'&&!hasAttention(c))return false;if(quick==='content'&&!(postsFor(c)>0&&(c.postsDone||0)<postsFor(c)))return false;if(quick==='ending'&&!(daysUntil(c.end)>=0&&daysUntil(c.end)<=30))return false;if(quick==='paused'&&c.status!=='Gepauzeerd')return false;if(quick==='payment'&&!(c.installments||[]).some(i=>i.status!=='paid'))return false;return true});$('#clientTable').innerHTML=`<div class="client-result-count">${list.length} klant${list.length===1?'':'en'} gevonden</div><div class="table-card"><table class="table"><thead><tr><th>Klant</th><th>${isL?'Pakket':'Traject'}</th><th>Startdatum</th>${isL?'<th>Content deze maand</th>':'<th>Einddatum</th><th>Betaling</th>'}<th>Status</th><th>Tarief</th><th>Aandacht</th></tr></thead><tbody>${list.map(c=>{const l=activeLink(c),svc=serviceById(l?.serviceId),openPayments=(c.installments||[]).filter(i=>i.status!=='paid'),overdue=openPayments.filter(i=>daysUntil(i.due)<0),attention=isL?lynqAttention(c):notifications().filter(n=>n.clientId===c.id&&n.priority!=='info');return `<tr class="clickrow" onclick="openClient('${c.id}')"><td><div class="entity"><div class="avatar-square">${initials(c.company)}</div><div><strong>${esc(c.company)}</strong><small>${esc(c.email)}</small></div></div></td><td>${esc(svc?.name||'—')}</td><td>${fmtDate(c.start)}</td>${isL?`<td><div class="content-at-glance"><strong>${Number(c.postsScheduled||0)} ingepland · ${Number(c.postsDone||0)} online</strong><small>${postsFor(c)||0} afgesproken · ${Math.max(0,postsFor(c)-Number(c.postsDone||0))} open</small><span><i style="width:${postsFor(c)?Math.min(100,Number(c.postsDone||0)/postsFor(c)*100):0}%"></i></span></div></td>`:`<td>${fmtDate(c.end)}</td><td><span class="chip ${overdue.length?'danger':openPayments.length?'warn':'ok'}">${overdue.length?'Achterstallig':openPayments.length?`${openPayments.length} open`:'Bij'}</span></td>`}<td><span class="chip ${c.status==='Actief'?'ok':c.status==='Gepauzeerd'?'warn':'wine'}">${c.status}</span></td><td>${money(l?.rate||0)}${svc?.billing==='monthly'?' / mnd':''}</td><td>${attention.length?`<div class="attention-cell"><span class="${attention.some(n=>n.priority==='urgent')?'urgent':''}"></span><div><strong>${esc(attention[0].title)}</strong><small>${esc(attention[0].sub||'')}</small></div></div>`:'<span class="quiet-dash">—</span>'}</td></tr>`}).join('')||`<tr><td colspan="${isL?8:9}">Geen klanten gevonden.</td></tr>`}</tbody></table></div>`}
function services(){return `<div class="page">${pageHead(state.workspace==='lynq'?'Pakketten':'Trajecten',state.workspace==='lynq'?'Beheer de pakketcatalogus. Bestaande klantafspraken blijven los van cataloguswijzigingen.':'Beheer trajecten en standaardprijzen. Bestaande klantafspraken blijven los van cataloguswijzigingen.','<button class="primary wine-btn" onclick="openServiceForm()">+ Nieuw</button>')}<div class="catalog-grid">${workspace().services.map(s=>`<div class="catalog-card"><img class="catalog-cover" style="object-position:50% ${serviceImagePosition(s)}%" src="${s.image||'assets/website-service.svg'}" alt=""><div class="catalog-body"><span class="chip ${s.billing==='monthly'?'wine':'neutral'}">${s.billing==='monthly'?'Maandelijks':'Eenmalig'}</span><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p><div class="catalog-foot"><div class="catalog-price"><strong>${money(s.price)}${s.billing==='monthly'?' / maand':''}</strong>${state.workspace==='lynq'?`<small>${s.posts||0} posts per maand</small>`:''}</div><button class="outline" onclick="openServiceForm('${s.id}')">Bewerken</button></div></div></div>`).join('')}</div></div>`}
function content(){const clients=workspace().clients.filter(c=>postsFor(c)>0),shown=clients.filter(c=>{const h=contentHealth(c);if(state.contentFilter==='attention')return h.behind;if(state.contentFilter==='complete')return h.complete;return true}),total=clients.reduce((a,c)=>a+postsFor(c),0),done=clients.reduce((a,c)=>a+Number(c.postsDone||0),0),open=Math.max(0,total-done),attention=clients.filter(c=>contentHealth(c).behind).length;return `<div class="page">${pageHead('Content','Per klant zie je direct wat afgesproken is, wat online staat en waar aandacht nodig is.')}<div class="content-summary-kpis"><div class="content-summary-kpi"><span>Afgesproken deze maand</span><strong>${total}</strong><small>posts over alle klanten</small></div><div class="content-summary-kpi"><span>Online</span><strong>${done}</strong><small>${total?Math.round(done/total*100):0}% afgerond</small></div><div class="content-summary-kpi"><span>Nog open</span><strong>${open}</strong><small>nog te publiceren</small></div><div class="content-summary-kpi"><span>Aandacht</span><strong>${attention}</strong><small>klanten achter schema</small></div></div><div class="content-toolbar-modern"><div class="saved-filters"><button class="saved-filter ${state.contentFilter==='all'?'active':''}" onclick="state.contentFilter='all';render()">Alles</button><button class="saved-filter ${state.contentFilter==='attention'?'active':''}" onclick="state.contentFilter='attention';render()">Aandacht nodig</button><button class="saved-filter ${state.contentFilter==='complete'?'active':''}" onclick="state.contentFilter='complete';render()">Voltooid</button></div><span>${shown.length} klant${shown.length===1?'':'en'}</span></div><div class="content-client-grid">${shown.map(c=>contentClientCard(c,false)).join('')||'<div class="section-card empty-state-v9">Geen klanten binnen dit filter.</div>'}</div></div>`}
function installments(){
  const rows=allInstallments(), openRows=rows.filter(x=>x.effectiveStatus!=='paid'), now=new Date();
  const expected=openRows.reduce((a,x)=>a+Number(x.i.amount||0),0),received=rows.filter(x=>x.effectiveStatus==='paid').reduce((a,x)=>a+Number(x.i.amount||0),0),overdue=rows.filter(x=>x.effectiveStatus==='overdue').reduce((a,x)=>a+Number(x.i.amount||0),0);
  const monthEnd=new Date(now.getFullYear(),now.getMonth()+1,0);const thisMonth=openRows.filter(x=>{const d=new Date(x.i.due+'T12:00:00');return d>=now&&d<=monthEnd}).reduce((a,x)=>a+Number(x.i.amount||0),0);
  return `<div class="page payments-page">${pageHead('Termijnbetalingen','Een rustig financieel overzicht met vaste kolommen, duidelijke statussen en directe acties.')}<div class="payment-kpis">${paymentMetric('Nog te ontvangen',money(expected),'Alle open termijnen')}${paymentMetric('Deze maand',money(thisMonth),'Nog verwacht deze maand')}${paymentMetric('Achterstallig',money(overdue),overdue?'Direct opvolgen':'Alles op tijd')}${paymentMetric('Ontvangen',money(received),'Geregistreerd betaald')}</div><div class="payment-toolbar"><div class="saved-filters payment-tabs"><button class="saved-filter active" data-payfilter="all">Alles</button><button class="saved-filter" data-payfilter="open">Openstaand</button><button class="saved-filter" data-payfilter="upcoming">Binnenkort</button><button class="saved-filter" data-payfilter="overdue">Achterstallig</button><button class="saved-filter" data-payfilter="paid">Betaald</button></div><span>${rows.length} termijnen</span></div><div id="paymentRows"></div></div>`
}
function paymentMetric(label,value,sub){return `<div class="payment-kpi"><span>${label}</span><strong>${value}</strong><small>${sub}</small></div>`}
function renderPayments(){
  if(!$('#paymentRows'))return;const filter=document.querySelector('[data-payfilter].active')?.dataset.payfilter||'all';
  const rows=allInstallments().filter(x=>{const d=daysUntil(x.i.due);if(filter==='all')return true;if(filter==='upcoming')return x.effectiveStatus==='open'&&d>0&&d<=14;return x.effectiveStatus===filter});
  $('#paymentRows').innerHTML=`<div class="payment-table-card"><div class="payment-table-head"><span>Klant / traject</span><span>Termijn</span><span>Vervaldatum</span><span>Bedrag</span><span>Betaald</span><span>Status</span><span></span></div>${rows.sort((a,b)=>a.i.due.localeCompare(b.i.due)).map(({c,i,effectiveStatus})=>{const all=c.installments||[],paid=all.filter(x=>x.status==='paid').reduce((a,x)=>a+Number(x.amount||0),0),total=all.reduce((a,x)=>a+Number(x.amount||0),0),pct=total?Math.round(paid/total*100):0,svc=serviceById(activeLink(c)?.serviceId);return `<div class="payment-table-row ${effectiveStatus}"><button class="payment-client" onclick="openClient('${c.id}')"><div class="avatar-square">${initials(c.contact)}</div><div><strong>${esc(c.contact)}</strong><small>${esc(svc?.name||'Traject')}</small></div></button><div class="payment-term"><strong>${i.nr} van ${all.length}</strong><small>termijn</small></div><div class="payment-due"><strong>${fmtDate(i.due)}</strong><small>${effectiveStatus==='overdue'?Math.abs(daysUntil(i.due))+' dagen te laat':effectiveStatus==='paid'?'afgerond':daysUntil(i.due)===0?'vandaag':daysUntil(i.due)>0?'over '+daysUntil(i.due)+' dagen':''}</small></div><strong class="payment-amount">${money(i.amount)}</strong><div class="payment-progress compact"><span>${money(paid)} / ${money(total)}</span><i><b style="width:${pct}%"></b></i></div><span class="chip ${effectiveStatus==='paid'?'ok':effectiveStatus==='overdue'?'danger':'warn'}">${effectiveStatus==='paid'?'Betaald':effectiveStatus==='overdue'?'Achterstallig':effectiveStatus==='today'?'Vandaag':'Openstaand'}</span><div class="payment-actions">${effectiveStatus!=='paid'?`<button class="outline" onclick="markInstallment('${c.id}','${i.id}')">Als betaald</button>`:''}<button class="ghost" onclick="openClient('${c.id}')">Open →</button></div></div>`}).join('')||'<div class="empty-state-v9">Geen betalingen binnen dit filter.</div>'}</div>`
}

function contentItemsForClient(c){return c.contentPlan||[]}
function allContentItems(){return workspace().clients.flatMap(c=>contentItemsForClient(c).map(item=>({c,item}))).sort((a,b)=>(a.item.date||'').localeCompare(b.item.date||'')||(a.item.time||'').localeCompare(b.item.time||''))}
function contentStatusLabel(s){return({idea:'Idee',draft:'In concept',input:'Wachten op input',review:'Klaar voor review',scheduled:'Ingepland',published:'Gepubliceerd'}[s]||s||'Idee')}
function contentStatusClass(s){return s==='published'?'published':s==='scheduled'?'scheduled':s==='review'?'review':s==='input'?'input':s==='draft'?'draft':'idea'}
function contentTypeLabel(t){return({talk:'Praatvideo',reel:'Reel',interview:'Interview klant',carousel:'Carousel',story:'Story',photo:'Foto post',tiktok:'TikTok',linkedin:'LinkedIn post'}[t]||t||'Content')}
function contentCalendar(items,clientOnly=false){
 const month=state.contentMonth||new Date().toISOString().slice(0,7),[y,m]=month.split('-').map(Number),first=new Date(y,m-1,1),last=new Date(y,m,0),startOffset=(first.getDay()+6)%7,totalCells=Math.ceil((startOffset+last.getDate())/7)*7;
 const monthLabel=first.toLocaleDateString('nl-NL',{month:'long',year:'numeric'});
 const byDate={};items.forEach(x=>{const item=x.item||x,c=x.c;if(!item.date)return;(byDate[item.date]??=[]).push({item,c})});
 const days=Array.from({length:totalCells},(_,idx)=>{const day=idx-startOffset+1;if(day<1||day>last.getDate())return '<div class="planner-cal-day muted-day"></div>';const date=`${month}-${String(day).padStart(2,'0')}`,entries=byDate[date]||[];return `<div class="planner-cal-day"><div class="planner-cal-date">${day}</div><div class="planner-cal-items">${entries.slice(0,4).map(({item,c})=>`<button class="planner-cal-item ${contentStatusClass(item.status)}" onclick="openContentForm('${c?.id||state.clientId}','${item.id}')"><span>${esc(item.time||'')}</span><strong>${esc(item.concept||'Content')}</strong>${!clientOnly&&c?`<small>${esc(c.company)}</small>`:''}</button>`).join('')}${entries.length>4?`<small class="planner-cal-more">+ ${entries.length-4} meer</small>`:''}</div></div>`}).join('');
 return `<div class="planner-calendar-wrap"><div class="planner-calendar-head"><button class="outline" onclick="changeContentMonth(-1)">‹</button><strong>${monthLabel}</strong><button class="outline" onclick="changeContentMonth(1)">›</button></div><div class="planner-cal-weekdays">${['Ma','Di','Wo','Do','Vr','Za','Zo'].map(x=>`<span>${x}</span>`).join('')}</div><div class="planner-cal-grid">${days}</div></div>`
}
function changeContentMonth(delta){const [y,m]=(state.contentMonth||new Date().toISOString().slice(0,7)).split('-').map(Number),d=new Date(y,m-1+delta,1);state.contentMonth=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;render()}
function content(){
 const items=allContentItems(),scheduled=items.filter(x=>x.item.status==='scheduled').length,review=items.filter(x=>x.item.status==='review').length,missing=items.filter(x=>!x.item.asset&&['draft','review','scheduled'].includes(x.item.status)).length,published=items.filter(x=>x.item.status==='published').length;
 const clientFilter=state.contentClientFilter||'all',statusFilter=state.contentStatusFilter||'all',shown=items.filter(x=>(clientFilter==='all'||x.c.id===clientFilter)&&(statusFilter==='all'||x.item.status===statusFilter));
 const view=state.contentView||'list';
 return `<div class="page content-planner-page">${pageHead('Contentplanning','Alle klantcontent in één overzicht. Filter, plan en open direct het juiste klantdossier.','<button class="primary" onclick="openContentForm()">+ Content toevoegen</button>')}<div class="content-summary-kpis"><div class="content-summary-kpi"><span>Ingepland</span><strong>${scheduled}</strong><small>klaar om te publiceren</small></div><div class="content-summary-kpi"><span>Wacht op review</span><strong>${review}</strong><small>nog goedkeuren</small></div><div class="content-summary-kpi"><span>Zonder visual</span><strong>${missing}</strong><small>asset nog toevoegen</small></div><div class="content-summary-kpi"><span>Gepubliceerd</span><strong>${published}</strong><small>afgeronde content</small></div></div><div class="content-planner-toolbar"><div class="planner-filter"><label>Klant</label><select onchange="state.contentClientFilter=this.value;render()"><option value="all">Alle klanten</option>${workspace().clients.map(c=>`<option value="${c.id}" ${clientFilter===c.id?'selected':''}>${esc(c.company)}</option>`).join('')}</select></div><div class="planner-filter"><label>Status</label><select onchange="state.contentStatusFilter=this.value;render()"><option value="all">Alle statussen</option>${['idea','draft','input','review','scheduled','published'].map(v=>`<option value="${v}" ${statusFilter===v?'selected':''}>${contentStatusLabel(v)}</option>`).join('')}</select></div><div class="planner-view-switch"><button class="${view==='list'?'active':''}" onclick="state.contentView='list';render()">Lijst</button><button class="${view==='calendar'?'active':''}" onclick="state.contentView='calendar';render()">Kalender</button></div></div>${view==='calendar'?contentCalendar(shown,false):`<div class="content-plan-table"><div class="content-plan-head"><span>Datum</span><span>Klant</span><span>Concept / omschrijving</span><span>Status</span><span>Soort content</span><span>Platform</span><span></span></div>${shown.map(({c,item})=>contentPlanRow(c,item)).join('')||'<div class="empty-state-v9">Nog geen content binnen deze filters.</div>'}</div>`}</div>`
}
function contentPlanRow(c,item){return `<div class="content-plan-row"><div><strong>${fmtDate(item.date)}</strong><small>${esc(item.time||'')}</small></div><button class="content-client-link" onclick="openClient('${c.id}');state.tab='content';render()"><span class="avatar-square">${initials(c.company)}</span><b>${esc(c.company)}</b></button><button class="content-concept" onclick="openContentForm('${c.id}','${item.id}')"><strong>${esc(item.concept||'Zonder titel')}</strong><small>${esc(item.description||'Geen omschrijving')}</small></button><span class="content-status ${contentStatusClass(item.status)}">${contentStatusLabel(item.status)}</span><span class="content-type-pill">${contentTypeLabel(item.type)}</span><span class="platform-pill">${esc(item.platform||'—')}</span><button class="ghost" onclick="openContentForm('${c.id}','${item.id}')">Bewerken →</button></div>`}
function clientContentPlanner(c){const items=contentItemsForClient(c).slice().sort((a,b)=>(a.date||'').localeCompare(b.date||'')),view=state.contentView||'list';return `<div class="client-body"><div class="client-main"><div class="services-heading"><div><h2>Contentplanner</h2><p>De contentplanning van ${esc(c.company)}.</p></div><div class="client-content-actions"><div class="planner-view-switch"><button class="${view==='list'?'active':''}" onclick="state.contentView='list';render()">Lijst</button><button class="${view==='calendar'?'active':''}" onclick="state.contentView='calendar';render()">Kalender</button></div><button class="primary" onclick="openContentForm('${c.id}')">+ Content toevoegen</button></div></div>${view==='calendar'?contentCalendar(items.map(item=>({c,item})),true):`<div class="content-plan-table client-content-table"><div class="content-plan-head"><span>Datum</span><span>Concept / omschrijving</span><span>Status</span><span>Soort content</span><span>Platform</span><span></span></div>${items.map(item=>`<div class="content-plan-row client-row"><div><strong>${fmtDate(item.date)}</strong><small>${esc(item.time||'')}</small></div><button class="content-concept" onclick="openContentForm('${c.id}','${item.id}')"><strong>${esc(item.concept||'Zonder titel')}</strong><small>${esc(item.description||'Geen omschrijving')}</small></button><span class="content-status ${contentStatusClass(item.status)}">${contentStatusLabel(item.status)}</span><span class="content-type-pill">${contentTypeLabel(item.type)}</span><span class="platform-pill">${esc(item.platform||'—')}</span><button class="ghost" onclick="openContentForm('${c.id}','${item.id}')">Bewerken →</button></div>`).join('')||'<div class="empty-state-v9">Nog geen content voor deze klant.</div>'}</div>`}</div>${rightPanel(c)}</div>`}
function openContentForm(clientId='',itemId=''){
 const c=clientId?workspace().clients.find(x=>x.id===clientId):null,item=c?.contentPlan?.find(x=>x.id===itemId);openDrawer(`<div class="drawer-head"><div><div class="drawer-title">${item?'Content bewerken':'Nieuwe content'}</div><div class="page-sub">Plan content direct bij de juiste klant.</div></div><button class="closebtn" onclick="closeDrawer()">×</button></div><form id="contentForm"><div class="form-grid"><div class="field full"><label>Klant</label><select name="clientId" required ${c?'disabled':''}>${workspace().clients.map(x=>`<option value="${x.id}" ${(c?.id===x.id)?'selected':''}>${esc(x.company)}</option>`).join('')}</select></div><div class="field"><label>Datum</label><input type="date" name="date" value="${item?.date||''}" required></div><div class="field"><label>Tijd</label><input type="time" name="time" value="${item?.time||''}"></div><div class="field full"><label>Concept</label><input name="concept" value="${esc(item?.concept||'')}" placeholder="Bijv. Klantvideo of Reel"></div><div class="field full"><label>Omschrijving</label><textarea name="description" placeholder="Onderwerp, invalshoek of boodschap">${esc(item?.description||'')}</textarea></div><div class="field"><label>Status</label><select name="status">${['idea','draft','input','review','scheduled','published'].map(v=>`<option value="${v}" ${item?.status===v?'selected':''}>${contentStatusLabel(v)}</option>`).join('')}</select></div><div class="field"><label>Soort content</label><select name="type">${['talk','reel','interview','carousel','story','photo','tiktok','linkedin'].map(v=>`<option value="${v}" ${item?.type===v?'selected':''}>${contentTypeLabel(v)}</option>`).join('')}</select></div><div class="field"><label>Platform</label><select name="platform">${['Instagram','TikTok','LinkedIn','Facebook','YouTube'].map(v=>`<option ${item?.platform===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Voorbeeld / link</label><input name="asset" value="${esc(item?.asset||'')}" placeholder="Link naar Canva, Drive..."></div><div class="field full"><label>Opmerkingen</label><textarea name="notes">${esc(item?.notes||'')}</textarea></div></div><div class="drawer-actions">${item?`<button type="button" class="outline danger-btn" onclick="deleteContentItem('${c.id}','${item.id}')">Verwijderen</button>`:''}<button type="button" class="outline" onclick="closeDrawer()">Annuleren</button><button class="primary">Opslaan</button></div></form>`);$('#contentForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),targetId=c?.id||f.get('clientId'),target=workspace().clients.find(x=>x.id===targetId);target.contentPlan=target.contentPlan||[];const obj={id:item?.id||uid('cp'),date:f.get('date'),time:f.get('time'),concept:f.get('concept'),description:f.get('description'),status:f.get('status'),type:f.get('type'),platform:f.get('platform'),asset:f.get('asset'),notes:f.get('notes')};if(item)Object.assign(item,obj);else target.contentPlan.push(obj);saveData('Contentplanning opgeslagen');closeDrawer();toast('Content opgeslagen');render()}}
function deleteContentItem(clientId,itemId){const c=workspace().clients.find(x=>x.id===clientId);if(!c||!confirm('Contentitem verwijderen?'))return;c.contentPlan=(c.contentPlan||[]).filter(x=>x.id!==itemId);saveData('Content verwijderd');closeDrawer();render()}

function taskDueState(task){if(task.status==='done')return'done';const d=daysUntil(task.date);if(d<0)return'overdue';if(d===0)return'today';if(d<=7)return'week';return'upcoming'}
function taskPrettyState(task){const st=taskDueState(task);return st==='done'?'Afgerond':st==='overdue'?'Te laat':st==='today'?'Vandaag':st==='week'?'Deze week':'Later'}
function taskRichRow(t){const st=taskDueState(t.task),svc=serviceById(activeLink(t.client)?.serviceId);return `<div class="task-work-row ${st} ${t.task.status==='done'?'done':''}"><button class="task-check" onclick="toggleTask('${t.client.id}','${t.task.id}')">${t.task.status==='done'?'✓':''}</button><div class="task-work-copy"><strong>${esc(t.task.title)}</strong><small>${esc(t.client.company)}${svc?` · ${esc(svc.name)}`:''}</small></div><span class="task-state-chip ${st}">${taskPrettyState(t.task)}</span><span class="task-work-date">${fmtDate(t.task.date)}</span><div class="task-work-actions"><button class="ghost" onclick="openClient('${t.client.id}')">Klant</button><button class="outline" onclick="editTask('${t.client.id}','${t.task.id}')">Bewerken</button></div></div>`}
function tasks(){
  const all=allTasks('all'), open=all.filter(t=>t.task.status!=='done'), done=all.filter(t=>t.task.status==='done');
  const overdue=open.filter(t=>taskDueState(t.task)==='overdue');
  const today=open.filter(t=>taskDueState(t.task)==='today');
  const week=open.filter(t=>taskDueState(t.task)==='week');
  const later=open.filter(t=>taskDueState(t.task)==='upcoming');
  const f=state.taskFilter||'open';
  const shown=f==='done'?done:f==='all'?all:open;
  return `<div class="page task-page">
    ${pageHead('Taken','Werk vanuit één overzicht: zie direct wat te laat is, vandaag moet gebeuren en wat later kan.','<button class="primary wine-btn" onclick="toast(\'Open een klant om een taak toe te voegen\')">+ Nieuwe taak</button>')}
    <div class="task-summary-grid">
      <div class="task-summary-card"><span>Open</span><strong>${open.length}</strong><small>nog af te ronden</small></div>
      <div class="task-summary-card"><span>Vandaag</span><strong>${today.length}</strong><small>direct oppakken</small></div>
      <div class="task-summary-card"><span>Te laat</span><strong>${overdue.length}</strong><small>prioriteit</small></div>
      <div class="task-summary-card"><span>Afgerond</span><strong>${done.length}</strong><small>historie</small></div>
    </div>
    <div class="task-layout-modern">
      <section class="section-card task-main-card">
        <div class="section-head">
          <div><strong>Werkoverzicht</strong><small>Filter op wat nu aandacht nodig heeft.</small></div>
          <div class="task-filter-row">
            <button class="outline ${f==='open'?'active':''}" onclick="state.taskFilter='open';render()">Open</button>
            <button class="outline ${f==='done'?'active':''}" onclick="state.taskFilter='done';render()">Afgerond</button>
            <button class="outline ${f==='all'?'active':''}" onclick="state.taskFilter='all';render()">Alle</button>
          </div>
        </div>
        <div class="task-work-list">${shown.map(taskRichRow).join('')||'<div class="empty-state-modern"><strong>Geen taken in deze filter</strong><span>Alles is bijgewerkt.</span></div>'}</div>
      </section>
      <aside class="task-side-col">
        <section class="section-card task-focus-card">
          <div class="section-head"><div><strong>Nu eerst doen</strong><small>De belangrijkste acties bovenaan.</small></div></div>
          <div class="task-priority-stack">
            <div class="task-priority-group"><b>Te laat</b>${overdue.slice(0,4).map(taskRichRow).join('')||'<div class="empty-inline">Geen taken te laat.</div>'}</div>
            <div class="task-priority-group"><b>Vandaag</b>${today.slice(0,4).map(taskRichRow).join('')||'<div class="empty-inline">Niets voor vandaag.</div>'}</div>
            <div class="task-priority-group"><b>Deze week</b>${week.slice(0,4).map(taskRichRow).join('')||'<div class="empty-inline">Geen taken deze week.</div>'}</div>
          </div>
        </section>
        <section class="section-card task-side-note">
          <div class="section-head"><div><strong>Later gepland</strong><small>Al ingepland, geen directe actie nodig.</small></div></div>
          <div class="task-later-list">${later.slice(0,5).map(t=>`<button class="task-later-row" onclick="openClient('${t.client.id}')"><div><strong>${esc(t.task.title)}</strong><small>${esc(t.client.company)} · ${fmtDate(t.task.date)}</small></div><i>→</i></button>`).join('')||'<div class="empty-inline">Geen latere taken.</div>'}</div>
        </section>
      </aside>
    </div>
  </div>`
}
function calendar(){const events=workspace().clients.flatMap(c=>(c.appointments||[]).map(a=>({c,a})));return `<div class="page">${pageHead('Afspraken','Leg klantafspraken vast. Dit is nog geen agendasynchronisatie.','<button class="primary wine-btn" onclick="toast(\'Open een klant om een afspraak toe te voegen\')">+ Afspraak</button>')}<div class="calendar-grid">${Array.from({length:21},(_,i)=>{const d=i+1;const es=events.filter((_,idx)=>idx%21===i);return `<div class="calendar-day"><b>${d} sep</b>${es.map(e=>`<div class="calendar-event">${esc(e.a.title)} · ${esc(e.c.company)}</div>`).join('')}</div>`}).join('')}</div></div>`}
function filesPage(){return `<div class="page">${pageHead('Bestanden','Ruimte voor klantbestanden en exports.')}<div class="section-card"><div class="integration-row"><div class="integration-icon">⇩</div><div class="integration-copy"><strong>Data exporteren</strong><small>Download alle lokale CRM-data als JSON.</small></div><button class="outline" onclick="exportJSON()">Exporteren</button></div><div class="integration-row"><div class="integration-icon">⇧</div><div class="integration-copy"><strong>Data importeren</strong><small>Herstel eerder geëxporteerde data.</small></div><button class="outline" onclick="$('#importFile').click()">Importeren</button></div></div></div>`}
function finance(){const rows=allFinanceItems(),filter=state.financeFilter||'open',shown=rows.filter(r=>filter==='all'||filter===r.status||(filter==='open'&&['open','today'].includes(r.status))||(filter==='soon'&&r.status==='open'&&daysUntil(r.item.due)<=7)),open=rows.filter(r=>r.status!=='paid'),paid=rows.filter(r=>r.status==='paid'),overdue=rows.filter(r=>r.status==='overdue'),sum=a=>a.reduce((t,r)=>t+Number(r.item.amount||0),0),bank=workspace().bankSettings||{};return `<div class="page">${pageHead('Financieel','Eén overzicht van wat betaald is, nog openstaat en aandacht nodig heeft.')}<div class="finance-connection-strip"><div><span class="connection-dot ${bank.connected?'connected':''}"></span><strong>${bank.connected?'Bankkoppeling actief':'Handmatige betaalcontrole'}</strong><small>${bank.connected?'Transactiesynchronisatie actief.':'Betalingen kunnen direct handmatig worden afgevinkt. Automatische bankkoppeling vereist backend + Open Banking.'}</small></div><button class="outline" onclick="state.settingsTab='bank';go('settings')">${bank.connected?'Beheer bank':'Bank koppelen'}</button></div><div class="payment-kpis">${paymentMetric('Openstaand',money(sum(open)),'Nog te ontvangen')}${paymentMetric('Ontvangen',money(sum(paid)),'Geregistreerd betaald')}${paymentMetric('Achterstallig',money(sum(overdue)),'Direct opvolgen')}${paymentMetric('Open betalingen',open.length,'Aantal betalingen')}</div><div class="saved-filters payment-tabs">${[['open','Openstaand'],['soon','Binnenkort'],['today','Vandaag'],['overdue','Achterstallig'],['paid','Betaald'],['all','Alles']].map(([k,l])=>`<button class="saved-filter ${filter===k?'active':''}" onclick="state.financeFilter='${k}';render()">${l}</button>`).join('')}</div><div class="tablewrap"><table class="table"><thead><tr><th>Klant</th><th>Omschrijving</th><th>Bedrag</th><th>Datum</th><th>Status</th><th></th></tr></thead><tbody>${shown.sort((a,b)=>(a.item.due||'').localeCompare(b.item.due||'')).map(r=>`<tr><td><button class="table-client-link" onclick="openClient('${r.c.id}')">${esc(r.c.company)}</button></td><td>${esc(r.item.label||'Betaling')}</td><td><strong>${money(r.item.amount)}</strong></td><td>${fmtDate(r.item.due)}</td><td><span class="chip ${r.status==='paid'?'ok':r.status==='overdue'?'danger':'warn'}">${r.status==='paid'?'Betaald':r.status==='overdue'?'Achterstallig':r.status==='today'?'Vandaag':'Openstaand'}</span></td><td>${r.status==='paid'?`<button class="ghost" onclick="reopenClientPayment('${r.c.id}','${r.item.id}')">Heropen</button>`:`<button class="outline" onclick="markClientPayment('${r.c.id}','${r.item.id}')">Als betaald</button>`}</td></tr>`).join('')||'<tr><td colspan="6">Geen betalingen binnen dit filter.</td></tr>'}</tbody></table></div></div>`}
function settings(){
  const accent=(localStorage.getItem(THEME_KEY)||DEFAULT_ACCENT).toUpperCase(),sub=(localStorage.getItem(SUBTHEME_KEY)||DEFAULT_SUB_ACCENT).toUpperCase(),tab=state.settingsTab||'brand',bank=workspace().bankSettings||{},apps=workspace().apps||[];
  const nav=[['brand','Huisstijl','Logo, kleuren & live preview'],['workspace','Werkruimtes','LYNQ & ShelingCynthia'],['bank','Bank & betalingen','Betaalcontrole & koppeling'],['apps','Apps & koppelingen','Jouw externe tools'],['notifications','Notificaties','Wanneer je gewaarschuwd wordt'],['data','Data & beveiliging','Opslag, export & backend']];let body='';
  if(tab==='brand') body=`<div class="settings-content-v19"><div class="settings-hero-card"><span class="settings-hero-icon">${settingsIcon('brand')}</span><div><span>Brand studio</span><h2>Maak de omgeving herkenbaar van Sheling</h2><p>Kies de primaire kleur en subkleur en zie direct hoe sidebar, knoppen, badges en kaarten eruit komen te zien.</p></div></div><div class="brand-studio-grid"><section class="settings-option-card brand-controls"><div class="settings-option-head"><div><strong>Kleuren</strong><small>Gebruik HEX of schuif door de kleurtoon. Alles wordt direct als preview getoond.</small></div></div><div class="brand-color-row"><div class="brand-color-title"><b>Primaire kleur</b><small>Sidebar, knoppen en actieve onderdelen</small></div><div class="modern-color-control"><label><span>Kleur</span><input id="brandPicker" type="color" value="${accent}" oninput="$('#brandHex').value=this.value.toUpperCase();applyBrandColor(this.value,false);updateBrandPreview()"></label><label><span>HEX</span><input id="brandHex" value="${accent}" maxlength="7" oninput="if(validHex(this.value)){applyBrandColor(this.value,false);updateBrandPreview()}"></label></div><label class="hue-control"><span>Kleurtoon</span><input type="range" min="0" max="360" value="${hueOf(accent)}" oninput="setHue('primary',this.value)"></label></div><div class="brand-color-row"><div class="brand-color-title"><b>Subkleur</b><small>Zachte vlakken, highlights en ondersteunende accenten</small></div><div class="modern-color-control"><label><span>Kleur</span><input id="subBrandPicker" type="color" value="${sub}" oninput="$('#subBrandHex').value=this.value.toUpperCase();applySubColor(this.value,false);updateBrandPreview()"></label><label><span>HEX</span><input id="subBrandHex" value="${sub}" maxlength="7" oninput="if(validHex(this.value)){applySubColor(this.value,false);updateBrandPreview()}"></label></div><label class="hue-control"><span>Kleurtoon</span><input type="range" min="0" max="360" value="${hueOf(sub)}" oninput="setHue('sub',this.value)"></label></div><div class="settings-card-actions"><button class="primary" onclick="setBrandColor($('#brandHex').value);setSubColor($('#subBrandHex').value);render()">Huisstijl opslaan</button><button class="outline" onclick="resetBrandStudio()">Herstel standaard</button></div></section><aside class="brand-live-card"><div class="brand-preview-label"><span>Live preview</span><small>Zo werkt de gekozen combinatie in de CRM.</small></div><div class="mini-app-preview"><div class="mini-sidebar" data-preview-primary><b>SHELINGCYNTHIA</b><span class="mini-nav-active">Vandaag</span><span>Klanten</span><span>Trajecten</span><span>Contentplanning</span></div><div class="mini-main"><div class="mini-top"><span></span><button data-preview-primary>+ Nieuwe klant</button></div><div class="mini-card"><small>Actieve klanten</small><strong>12</strong><div class="mini-progress"><i data-preview-primary></i></div></div><div class="mini-row"><span class="mini-avatar" data-preview-sub>SC</span><div><b>Studio Nova</b><small>Content Growth</small></div><em data-preview-primary-text>Op schema</em></div><div class="mini-actions"><button data-preview-primary>Opslaan</button><span data-preview-sub>Ingepland</span></div></div></div></aside></div></div>`;
  if(tab==='workspace') body=`<div class="settings-content-v19"><div class="settings-hero-card"><span class="settings-hero-icon">${settingsIcon('workspace')}</span><div><span>Werkruimtes</span><h2>Twee bedrijven, één CRM</h2><p>Gegevens blijven logisch gescheiden per werkruimte.</p></div></div><div class="workspace-choice-grid"><button class="workspace-choice-card ${state.workspace==='lynq'?'active':''}" onclick="state.workspace='lynq';state.page='dashboard';renderNav();render()"><span>LA</span><div><strong>LYNQ Agency</strong><small>Content, pakketten, betalingen en agency-klanten</small></div><i>${state.workspace==='lynq'?'Actief':'Open →'}</i></button><button class="workspace-choice-card ${state.workspace==='sheling'?'active':''}" onclick="state.workspace='sheling';state.page='dashboard';renderNav();render()"><span>SC</span><div><strong>ShelingCynthia</strong><small>Trajecten, pauzes, hervatten en termijnen</small></div><i>${state.workspace==='sheling'?'Actief':'Open →'}</i></button></div></div>`;
  if(tab==='bank') body=`<div class="settings-content-v19"><div class="settings-hero-card"><span class="settings-hero-icon">${settingsIcon('bank')}</span><div><span>Bank & betalingen</span><h2>Betaalstatus zonder zoekwerk</h2><p>Handmatig werkt nu al. Voor automatische transacties is een veilige Open Banking-koppeling nodig.</p></div><span class="settings-status ${bank.connected?'connected':''}">${bank.connected?'Verbonden':'Handmatig'}</span></div><div class="bank-choice-grid"><div class="bank-choice-card active"><div class="choice-radio">✓</div><div><strong>Handmatig bijhouden</strong><small>Markeer een betaling vanuit Financieel of direct in het klantdossier als betaald.</small></div><span>Werkt nu</span></div><div class="bank-choice-card"><div class="choice-radio"></div><div><strong>Automatische bankkoppeling</strong><small>Transacties automatisch herkennen en koppelen aan klanten en termijnen.</small></div><span>Backend nodig</span></div></div></div>`;
  if(tab==='apps') body=`<div class="settings-content-v19"><div class="settings-hero-card"><span class="settings-hero-icon">${settingsIcon('apps')}</span><div><span>Apps & koppelingen</span><h2>Al haar tools vanuit één plek</h2><p>Voeg zelf apps toe en open ze direct vanuit de CRM.</p></div><button class="primary" onclick="addCustomApp()">+ App toevoegen</button></div><div class="settings-apps-modern">${apps.map(a=>`<div class="settings-app-modern"><span class="real-app-icon large">${appIconSrc(a)?`<img src="${appIconSrc(a)}" alt="${esc(a.name)}">`:`<b>${esc(a.name?.[0]||'A')}</b>`}</span><div class="settings-app-copy"><strong>${esc(a.name)}</strong><small>${esc(appDomain(a.url))}</small></div><span class="app-link-status">Snelkoppeling</span><a href="${esc(a.url)}" target="_blank" class="icon-link-btn">↗</a><button class="icon-link-btn" onclick="editCustomApp('${a.id}')">•••</button></div>`).join('')||'<div class="empty">Nog geen apps toegevoegd.</div>'}</div></div>`;
  if(tab==='notifications'){
    const ns=loadNotificationSettings(),log=notificationLog().slice(0,6),backendReady=!!localStorage.getItem(NOTIFICATION_API_URL_KEY);
    const switches=[['trajectory_paused','Traject gepauzeerd','Direct wanneer een traject wordt gepauzeerd.','Ⅱ'],['trajectory_resumed','Traject hervat','Direct wanneer een traject weer actief wordt.','↻'],['trajectory_ended','Traject beëindigd','Direct wanneer een traject wordt afgesloten.','✓'],['payment_overdue','Betaling achterstallig','Zodra een open termijn over de vervaldatum is.','€'],['trajectory_ending','Traject loopt af','Binnen 30 dagen voor de einddatum.','◷'],['content_attention','Content vraagt aandacht','Wanneer content achter op planning raakt.','◇']];
    body=`<div class="settings-content-v19 notification-settings-page"><div class="settings-hero-card notification-hero"><span class="settings-hero-icon">${settingsIcon('notifications')}</span><div><span>Notificaties</span><h2>Belangrijke updates, zonder ruis</h2><p>De voorkeuren zijn nu al klaar. Zodra de backend wordt gekoppeld, kunnen deze gebeurtenissen automatisch per e-mail worden verstuurd.</p></div><span class="backend-ready-badge ${backendReady?'connected':''}"><i></i>${backendReady?'Backend verbonden':'Klaar voor backend'}</span></div><section class="settings-option-card notification-recipient-card"><div class="notification-recipient-copy"><span class="notification-mail-icon">@</span><div><strong>E-mailmeldingen</strong><small>Belangrijke updates worden voorbereid voor dit adres.</small></div></div><div class="notification-recipient-controls"><label class="switch-control"><input type="checkbox" ${ns.emailEnabled?'checked':''} onchange="updateNotificationSetting('emailEnabled',this.checked)"><span></span></label><label class="notification-email-field"><span>Ontvanger</span><input type="email" value="${esc(ns.email)}" onchange="updateNotificationSetting('email',this.value)" placeholder="naam@bedrijf.nl"></label></div></section><section class="notification-preferences-card"><div class="notification-section-head"><div><strong>Wanneer e-mailen?</strong><small>Sheling bepaalt zelf welke gebeurtenissen belangrijk genoeg zijn.</small></div><span>${switches.filter(([k])=>ns.events[k]).length} actief</span></div><div class="notification-preference-list">${switches.map(([k,title,sub,ico])=>`<label class="notification-preference-row"><span class="notification-pref-icon">${ico}</span><div><strong>${title}</strong><small>${sub}</small></div><span class="switch-control"><input type="checkbox" ${ns.events[k]?'checked':''} onchange="updateNotificationSetting('event:${k}',this.checked)"><span></span></span></label>`).join('')}</div></section><section class="notification-log-card"><div class="notification-section-head"><div><strong>Recente meldingen</strong><small>De software registreert deze nu al. Zonder backend blijft de status ‘Wacht op backend’.</small></div>${log.length?'<button class="ghost" onclick="clearNotificationLog()">Log wissen</button>':''}</div><div class="notification-log-list">${log.map(n=>`<div class="notification-log-row"><span class="notification-log-dot ${n.status}"></span><div><strong>${notificationTypeLabel(n.type)}</strong><small>${esc(n.payload?.clientName||'Algemeen')} · ${new Date(n.createdAt).toLocaleString('nl-NL',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</small></div><span class="notification-log-status ${n.status}">${notificationStatusLabel(n.status)}</span></div>`).join('')||'<div class="notification-log-empty">Nog geen belangrijke gebeurtenissen geregistreerd.</div>'}</div></section></div>`;
  }
  if(tab==='data') body=`<div class="settings-content-v19"><div class="settings-hero-card"><span class="settings-hero-icon">${settingsIcon('data')}</span><div><span>Data & beveiliging</span><h2>Houd controle over haar gegevens</h2><p>Deze versie bewaart data lokaal. Voor meerdere apparaten is een backend/login nodig.</p></div></div><div class="data-card-grid"><div class="data-modern-card"><span>⇩</span><div><strong>Export</strong><small>Download een kopie van de CRM-data.</small></div><button class="outline" onclick="exportJSON()">Exporteren</button></div><div class="data-modern-card"><span>⇧</span><div><strong>Import</strong><small>Zet eerder geëxporteerde data terug.</small></div><button class="outline" onclick="$('#importFile').click()">Importeren</button></div><div class="data-modern-card"><span>DB</span><div><strong>Database & login</strong><small>Vereist voor meerdere apparaten en echte sync.</small></div><span class="chip warn">Nog nodig</span></div></div></div>`;
  const navGroups=[['Omgeving',nav.slice(0,2)],['Beheer',nav.slice(2,5)],['Systeem',nav.slice(5)]];
  return `<div class="page settings-page-v19">${pageHead('Instellingen','Merk, werkruimtes, koppelingen en data op één rustige plek.')}<div class="settings-shell-v19"><aside class="settings-nav-v19"><div class="settings-nav-top"><span>Beheer</span><strong>Instellingen</strong></div>${navGroups.map(([group,items])=>`<div class="settings-nav-group"><div class="settings-nav-group-label">${group}</div>${items.map(([k,l,s])=>`<button class="${tab===k?'active':''}" onclick="state.settingsTab='${k}';render()"><span>${settingsIcon(k)}</span><div><strong>${l}</strong><small>${s}</small></div><i>›</i></button>`).join('')}</div>`).join('')}</aside><main>${body}</main></div></div>`

}

function openClient(id){state.clientId=id;state.page='client';state.tab='overview';render();renderNav();$('#mainScroll').scrollTop=0}
function clientDetail(){const c=workspace().clients.find(x=>x.id===state.clientId);if(!c){go('clients');return''}const tabs=state.workspace==='lynq'?['overview','onboarding','services','content','proposals','tasks','finance','notes','timeline','files','access']:['overview','services','tasks','finance','notes','timeline','files','access'];const labels={content:'Contentplanner',proposals:'Voorstellen',overview:'Overzicht',services:state.workspace==='lynq'?'Pakketten':'Trajecten',onboarding:'Onboarding',finance:'Financieel',tasks:'Taken',files:'Bestanden',access:'Toegang & techniek',notes:'Notities',timeline:'Tijdlijn'};const p=state.workspace==='lynq'?currentPeriod(c):null;return `<div class="client-page solveire-client-layout"><section class="client-hero"><div class="client-hero-inner"><button class="client-back" onclick="go('clients')">← Terug naar klanten</button><div class="client-top"><div class="client-id"><div class="client-logo editable">${initials(c.company)}</div><div><div class="client-title-row"><div class="client-title">${esc(c.company)}</div><span class="chip ${c.status==='Actief'?'ok':c.status==='Gepauzeerd'?'warn':'wine'}">${c.status}</span></div><div class="client-contact-name">${esc(c.contact)}</div><div class="client-contactline"><span>✉ ${esc(c.email)}</span>${c.phone?`<span class="sep-dot">•</span><span>⌕ ${esc(c.phone)}</span>`:''}${c.website?`<span class="sep-dot">•</span><a href="https://${c.website.replace(/^https?:\/\//,'')}" target="_blank">◎ ${esc(c.website)} ↗</a>`:''}</div></div></div><div class="client-hero-right"><div class="client-actions"><button class="primary wine-btn" onclick="addTask('${c.id}')">+ Taak toevoegen</button><button class="outline square-action" onclick="editClient('${c.id}')">•••</button></div><div class="client-metrics">${state.workspace==='lynq'?`<div class="metric"><small>Startdatum</small><strong>${fmtDate(c.start)}</strong></div><div class="metric"><small>Huidige periode</small><strong>${fmtDate(p.start)} – ${fmtDate(p.end)}</strong></div><div class="metric"><small>Content</small><strong>${Number(c.postsDone||0)} / ${postsFor(c)||0} online</strong></div>`:`<div class="metric"><small>Startdatum</small><strong>${fmtDate(c.start)}</strong></div><div class="metric"><small>Einddatum</small><strong>${fmtDate(c.end)}</strong></div>`}</div></div></div><div class="client-tabs">${tabs.map(t=>`<button class="client-tab ${state.tab===t?'active':''}" onclick="state.tab='${t}';render()">${labels[t]}${t==='tasks'?` <span class="chip neutral">${(c.tasks||[]).filter(t=>t.status==='open').length}</span>`:''}</button>`).join('')}</div></div></section>${clientTabBody(c)}</div>`}
function clientTabBody(c){if(state.tab==='content'&&state.workspace==='lynq')return clientContentPlanner(c);if(state.tab==='proposals'&&state.workspace==='lynq')return `<div class="client-body"><div class="client-main">${proposalOverview(c.id)}</div>${rightPanel(c)}</div>`;if(state.tab==='overview')return overviewTab(c);if(state.tab==='services')return servicesTab(c);if(state.tab==='onboarding')return onboardingTab(c);if(state.tab==='finance')return clientFinanceTab(c);if(state.tab==='tasks')return `<div class="client-body"><div class="client-main"><div class="services-heading"><div><h2>Taken</h2><p>Open en afgeronde taken voor deze klant.</p></div><button class="outline" onclick="addTask('${c.id}')">+ Taak toevoegen</button></div><div class="open-tasks-card" style="margin-top:0">${(c.tasks||[]).map(t=>taskRow(c,t)).join('')||'<div class="empty">Geen taken.</div>'}</div></div>${rightPanel(c)}</div>`;if(state.tab==='notes')return clientNotesTab(c);if(state.tab==='timeline')return clientTimelineTab(c);if(state.tab==='access')return accessTab(c);if(state.tab==='files')return `<div class="client-body"><div class="client-main"><div class="section-card"><div class="section-head"><strong>Bestanden</strong></div><div class="empty">Bestandsopslag wordt gekoppeld wanneer de eigen backend/storage wordt aangesloten.</div></div></div>${rightPanel(c)}</div>`;return servicesTab(c)}
function clientNotesTab(c){const notes=(c.notes||[]).slice().sort((a,b)=>(b.date||'').localeCompare(a.date||''));return `<div class="client-body"><div class="client-main"><div class="services-heading"><div><h2>Notities</h2><p>Laatste notitie bovenaan, zodat je direct ziet wat er het meest recent is vastgelegd.</p></div><button class="outline" onclick="addNote('${c.id}')">+ Nieuwe notitie</button></div><div class="notes-list-card">${notes.map((n,idx)=>`<div class="note-list-row"><div class="note-list-date"><strong>${fmtDate(n.date)}</strong>${idx===0?'<span>Laatste</span>':''}</div><div class="note-list-text">${esc(n.text)}</div><button class="ghost" onclick="editNote('${c.id}','${n.id}')">Bewerken</button></div>`).join('')||'<div class="empty notes-list-empty">Nog geen notities.</div>'}</div></div>${rightPanel(c)}</div>`}
function clientTimelineItems(c){const items=[];if(c.start)items.push({date:c.start,type:'Klant',title:'Start samenwerking',text:c.status?`Status: ${c.status}`:''});if(c.end)items.push({date:c.end,type:'Klant',title:'Einddatum',text:'Geplande einddatum van de samenwerking.'});(c.serviceLinks||[]).forEach(l=>{const s=serviceById(l.serviceId);(l.pauseHistory||[]).forEach(p=>{if(p.start)items.push({date:p.start,type:'Pauze',title:`${s?.name||'Traject'} gepauzeerd`,text:[p.note,p.resumePlanned?`Gepland hervatten: ${fmtDate(p.resumePlanned)}`:''].filter(Boolean).join(' · ')});if(p.resumedAt)items.push({date:p.resumedAt,type:'Hervatting',title:`${s?.name||'Traject'} hervat`,text:''})});if(l.endedAt)items.push({date:l.endedAt,type:'Traject',title:`${s?.name||'Traject'} beëindigd`,text:'Historie blijft bewaard.'})});(c.notes||[]).forEach(n=>items.push({date:n.date,type:'Notitie',title:'Notitie toegevoegd',text:n.text}));(c.tasks||[]).forEach(t=>items.push({date:t.date,type:'Taak',title:t.title,text:t.status==='done'?'Afgerond':'Open'}));(c.appointments||[]).forEach(a=>items.push({date:a.date,type:'Afspraak',title:a.title,text:a.time||''}));financeItemsForClient(c).forEach(i=>items.push({date:i.paidDate||i.due,type:'Betaling',title:i.label||'Betaling',text:`${money(i.amount)} · ${financeStatus(i)==='paid'?'Betaald':financeStatus(i)==='overdue'?'Achterstallig':'Openstaand'}`}));return items.filter(x=>x.date).sort((a,b)=>(b.date||'').localeCompare(a.date||''))}
function clientTimelineTab(c){const items=clientTimelineItems(c);return `<div class="client-body"><div class="client-main"><div class="services-heading"><div><h2>Tijdlijn</h2><p>Chronologisch overzicht van klantmomenten, taken, afspraken, betalingen en notities.</p></div></div><div class="timeline">${items.map(i=>`<div class="timeline-note"><small>${fmtDate(i.date)} · ${esc(i.type)}</small><p><strong>${esc(i.title)}</strong>${i.text?`<br>${esc(i.text)}`:''}</p></div>`).join('')||'<div class="empty">Nog geen gebeurtenissen op de tijdlijn.</div>'}</div></div>${rightPanel(c)}</div>`}
function overviewTab(c){const attention=state.workspace==='lynq'?lynqAttention(c):notifications().filter(n=>n.clientId===c.id&&n.priority!=='info');return `<div class="client-body solveire-overview-body"><div class="client-main">${attention.length?`<div class="attention-strip card"><div class="card-title">Aandacht nodig</div>${attention.slice(0,3).map(n=>`<div class="attention-line"><span class="${n.priority==='urgent'?'urgent':''}"></span><div><strong>${esc(n.title)}</strong><small>${esc(n.sub||'')}</small></div></div>`).join('')}</div>`:''}<div class="services-heading"><div><h2>${state.workspace==='lynq'?'Pakketten':'Trajecten'} voor ${esc(c.company)}</h2><p>Alles wat je voor deze klant verzorgt.</p></div><button class="outline" onclick="linkService('${c.id}')">+ ${state.workspace==='lynq'?'Pakket':'Traject'} koppelen</button></div><div class="customer-service-grid solveire-service-grid">${serviceCards(c)}</div><div class="open-tasks-card solveire-open-tasks"><div class="task-head"><strong>Open taken</strong><button class="ghost" onclick="state.tab='tasks';render()">Alle taken →</button></div>${(c.tasks||[]).filter(t=>t.status==='open').map(t=>taskRow(c,t)).join('')||'<div class="empty">Geen open taken.</div>'}</div></div>${rightPanel(c)}</div>`}
function servicesTab(c){return `<div class="client-body"><div class="client-main"><div class="services-heading"><div><h2>Gekoppelde ${state.workspace==='lynq'?'pakketten':'trajecten'}</h2><p>Tariefafspraken en historie blijven per klant bewaard.</p></div><button class="outline" onclick="linkService('${c.id}')">+ Koppelen</button></div><div class="customer-service-grid">${serviceCards(c,true)}</div></div>${rightPanel(c)}</div>`}
function onboardingTab(c){if(state.workspace!=='lynq')return servicesTab(c);const items=onboardingChecklist(c),done=items.filter(x=>x.done).length,pct=Math.round(done/items.length*100);return `<div class="client-body"><div class="client-main"><div class="section-card onboarding-card"><div class="section-head"><div><strong>Onboarding</strong><small>${done} van ${items.length} afgerond</small></div><span class="chip ${pct===100?'ok':'neutral'}">${pct}%</span></div><div class="onboarding-progress"><i style="width:${pct}%"></i></div>${items.map(x=>`<button class="onboarding-row ${x.done?'done':''}" onclick="toggleOnboarding('${c.id}','${x.key}')"><span>${x.done?'✓':''}</span><div>${x.label}</div></button>`).join('')}</div></div>${rightPanel(c)}</div>`}
function accessTab(c){const items=[['instagram','Instagram'],['facebook','Facebook'],['linkedin','LinkedIn'],['canva','Canva'],['notionAccess','Notion'],['drive','Google Drive']];c.access=c.access||{};return `<div class="client-body"><div class="client-main"><div class="section-card"><div class="section-head"><div><strong>Toegang & techniek</strong><small>Houd alleen bij of toegang geregeld is. Bewaar geen wachtwoorden.</small></div></div><div class="access-grid">${items.map(([k,l])=>`<button class="access-item ${c.access[k]?'ready':''}" onclick="toggleAccess('${c.id}','${k}')"><span>${c.access[k]?'✓':'○'}</span><div><strong>${l}</strong><small>${c.access[k]?'Toegang geregeld':'Nog nodig'}</small></div></button>`).join('')}</div><div class="form-grid access-links-form"><div class="field full"><label>Notion-link</label><input value="${esc(c.notion||'')}" onchange="updateField('${c.id}','notion',this.value)" placeholder="https://notion.so/..."></div></div></div></div>${rightPanel(c)}</div>`}

function serviceLinkState(l){if(!l)return'inactive';if(l.status==='ended')return'ended';if(l.status==='paused')return'paused';return'active'}
function pausePackage(clientId,linkId){
  const c=workspace().clients.find(x=>x.id===clientId),l=(c?.serviceLinks||[]).find(x=>x.id===linkId);
  if(!l){toast('Deze koppeling kon niet worden gevonden. Vernieuw de pagina en probeer opnieuw.');return}
  const today=new Date().toISOString().slice(0,10);
  const start=prompt('Pauze vanaf (YYYY-MM-DD):',today);
  if(!start)return;
  const resume=prompt('Geplande hervatdatum (YYYY-MM-DD, optioneel):',l.resumeDate||'');
  const note=prompt('Reden / notitie (optioneel):',l.pauseNote||'')||'';
  l.status='paused';
  l.pauseStart=start;
  l.resumeDate=resume||'';
  l.pauseNote=note;
  l.pauseHistory=l.pauseHistory||[];
  l.pauseHistory.push({id:uid('ph'),start,resumePlanned:resume||'',resumedAt:'',note});
  if(state.workspace==='sheling')c.status='Gepauzeerd';
  saveData('Traject gepauzeerd');
  const svc=serviceById(l.serviceId);queueNotificationEvent('trajectory_paused',{clientId:c.id,clientName:c.contact||c.company,serviceName:svc?.name||'Traject',pauseStart:start,resumeDate:resume||'',note},`trajectory_paused:${c.id}:${l.id}:${start}`);
  toast('Pauze opgeslagen');
  render()
}
function resumePackage(clientId,linkId){
  const c=workspace().clients.find(x=>x.id===clientId),l=(c?.serviceLinks||[]).find(x=>x.id===linkId);
  if(!l){toast('Deze koppeling kon niet worden gevonden.');return}
  const today=new Date().toISOString().slice(0,10);
  l.status='active';
  l.resumedAt=today;
  l.pauseHistory=l.pauseHistory||[];
  const current=[...l.pauseHistory].reverse().find(p=>!p.resumedAt);
  if(current)current.resumedAt=today;
  l.pauseStart='';
  l.resumeDate='';
  l.pauseNote='';
  if(state.workspace==='sheling')c.status='Actief';
  saveData('Traject hervat');
  const svc=serviceById(l.serviceId);queueNotificationEvent('trajectory_resumed',{clientId:c.id,clientName:c.contact||c.company,serviceName:svc?.name||'Traject',resumedAt:today},`trajectory_resumed:${c.id}:${l.id}:${today}`);
  toast('Traject hervat');
  render()
}
function endPackage(clientId,linkId){
  const c=workspace().clients.find(x=>x.id===clientId),l=(c?.serviceLinks||[]).find(x=>x.id===linkId);
  if(!l){toast('Deze koppeling kon niet worden gevonden.');return}
  if(!confirm('Beëindigen? De volledige historie blijft bewaard.'))return;
  const today=new Date().toISOString().slice(0,10);
  l.status='ended';
  l.endedAt=today;
  l.pauseHistory=l.pauseHistory||[];
  const current=[...l.pauseHistory].reverse().find(p=>!p.resumedAt);
  if(current&&!current.resumedAt)current.resumedAt=today;
  if(state.workspace==='sheling')c.status='Afgerond';
  saveData('Traject beëindigd');
  const svc=serviceById(l.serviceId);queueNotificationEvent('trajectory_ended',{clientId:c.id,clientName:c.contact||c.company,serviceName:svc?.name||'Traject',endedAt:today},`trajectory_ended:${c.id}:${l.id}:${today}`);
  toast('Traject beëindigd');
  render()
}
function reactivatePackage(clientId,linkId){
  const c=workspace().clients.find(x=>x.id===clientId),l=(c?.serviceLinks||[]).find(x=>x.id===linkId);
  if(!l){toast('Deze koppeling kon niet worden gevonden.');return}
  l.status='active';
  l.pauseStart='';
  l.resumeDate='';
  l.pauseNote='';
  l.endedAt='';
  if(state.workspace==='sheling')c.status='Actief';
  saveData('Traject heractiveerd');
  toast('Traject heractiveerd');
  render()
}
function packageResumeAlerts(){const out=[];(workspace().clients||[]).forEach(c=>(c.serviceLinks||[]).forEach(l=>{if(l.status==='paused'&&l.resumeDate){const d=daysUntil(l.resumeDate),s=serviceById(l.serviceId);if(d>=0&&d<=30)out.push({clientId:c.id,title:`${s?.name||'Pakket'} hervat ${d===0?'vandaag':`over ${d} dagen`}`,sub:c.company,priority:d<=1?'urgent':'attention',page:'client'})}}));return out}

function clientAttention(c){const ns=notifications().filter(n=>n.clientId===c.id&&n.priority!=='info');if(state.workspace==='lynq'){const open=Math.max(0,postsFor(c)-(c.postsDone||0));if(open)ns.unshift({title:`${open} posts nog open`,sub:`${c.postsDone||0} van ${postsFor(c)} online`,priority:'attention'})}if(!ns.length)return'';return `<div class="side-card client-attention-card"><h3>Aandacht</h3>${ns.slice(0,4).map(n=>`<div class="client-attention-item"><span></span><div><strong>${esc(n.title)}</strong><small>${esc(n.sub||'')}</small></div></div>`).join('')}</div>`}
function rightPanel(c){return `<aside class="right-panel"><div class="side-card"><h3>Contactpersoon</h3><div class="contact-person"><div class="contact-avatar">${initials(c.contact)}</div><div><strong>${esc(c.contact)}</strong><div><span class="chip ok">Primair</span></div></div></div><dl class="details"><dt>Telefoon</dt><dd>${esc(c.phone||'—')}</dd><dt>E-mail</dt><dd>${esc(c.email)}</dd><dt>Bedrijf</dt><dd>${esc(c.company)}</dd><dt>KVK</dt><dd>${esc(c.kvk||'—')}</dd><dt>Adres</dt><dd>${esc(c.address||'—')}</dd><dt>Website</dt><dd>${c.website?`<a href="https://${c.website.replace(/^https?:\/\//,'')}" target="_blank">${esc(c.website)} ↗</a>`:'—'}</dd></dl></div>${clientAttention(c)}<div class="side-card"><div class="note-card-head"><h3 style="margin:0">Notities</h3><button class="ghost" onclick="addNote('${c.id}')">+ Nieuw</button></div>${(c.notes||[]).length?`<div class="note-preview">${esc(c.notes[c.notes.length-1].text)}</div><div class="note-meta">${fmtDate(c.notes[c.notes.length-1].date)}</div><button class="ghost" style="margin-top:8px" onclick="state.tab='notes';render()">Alle notities (${c.notes.length}) →</button>`:'<div class="empty">Nog geen notities.</div>'}</div></aside>`}
function appDomain(url){try{return new URL(url).hostname.replace(/^www\./,'')}catch(e){return''}}
function appIconSrc(app){const d=appDomain(app.url||'');return d?`https://icons.duckduckgo.com/ip3/${d}.ico`:''}
function settingsIcon(name){const icons={brand:'◈',workspace:'▣',bank:'€',apps:'⊞',notifications:'◎',data:'⌁'};return icons[name]||'•'}
function clientFinanceTab(c){const s=financeSummaryForClient(c),items=s.items.slice().sort((a,b)=>(a.due||'').localeCompare(b.due||''));return `<div class="client-body"><div class="client-main"><div class="client-finance-summary"><div><small>Totaal</small><strong>${money(s.total)}</strong></div><div><small>Betaald</small><strong>${money(s.paid)}</strong></div><div><small>Openstaand</small><strong>${money(s.open)}</strong></div><div><small>Achterstallig</small><strong>${money(s.overdue)}</strong></div></div><div class="section-card"><div class="section-head"><div><strong>${state.workspace==='sheling'?'Termijnbetalingen':'Betalingen'}</strong><small>Alle betaalafspraken voor deze klant.</small></div><button class="outline" onclick="addClientPayment('${c.id}')">+ Betaling toevoegen</button></div><div>${items.map(i=>{const st=financeStatus(i);return `<div class="client-payment-row"><div><strong>${esc(i.label||'Betaling')}</strong><small>${fmtDate(i.due)}${i.paidDate?` · betaald ${fmtDate(i.paidDate)}`:''}</small></div><strong>${money(i.amount)}</strong><span class="chip ${st==='paid'?'ok':st==='overdue'?'danger':'warn'}">${st==='paid'?'Betaald':st==='overdue'?'Achterstallig':st==='today'?'Vandaag':'Openstaand'}</span><div>${st==='paid'?`<button class="ghost" onclick="reopenClientPayment('${c.id}','${i.id}')">Heropen</button>`:`<button class="outline" onclick="markClientPayment('${c.id}','${i.id}')">Als betaald</button>`}</div></div>`}).join('')||'<div class="empty">Nog geen betalingen toegevoegd.</div>'}</div></div></div>${rightPanel(c)}</div>`}function serviceCards(c,includeEnded=false){const links=(c.serviceLinks||[]).filter(l=>includeEnded||serviceLinkState(l)!=='ended');if(!links.length)return'<div class="empty">Nog niets gekoppeld.</div>';return links.map(l=>{const s=serviceById(l.serviceId),st=serviceLinkState(l);if(!s)return'';const img=s.image?`<img class="customer-service-image" style="object-position:50% ${serviceImagePosition(s)}%" src="${s.image}" alt="">`:`<div class="customer-service-image service-placeholder">${icon('services')}</div>`;return `<div class="customer-service-card service-state-${st}">${img}<div class="service-info"><div class="service-kicker"><span class="chip ${st==='active'?'ok':st==='paused'?'warn':'neutral'}">${st==='active'?'Actief':st==='paused'?'Gepauzeerd':'Beëindigd'}</span></div><div class="service-title">${esc(s.name)}</div><div class="service-price">${money(l.rate||s.price||0)}${s.billing==='monthly'?' / mnd':''}</div>${st==='paused'?`<div class="pause-meta"><strong>Pauze vanaf ${fmtDate(l.pauseStart)}</strong>${l.resumeDate?`<small>Hervat op ${fmtDate(l.resumeDate)}</small>`:'<small>Geen hervatdatum</small>'}${l.pauseNote?`<small>${esc(l.pauseNote)}</small>`:''}</div>`:''}</div><div class="service-actions-menu">${st==='active'?`<button class="tiny-action" onclick="event.stopPropagation();pausePackage('${c.id}','${l.id}')">Pauzeren</button><button class="tiny-action danger-text" onclick="event.stopPropagation();endPackage('${c.id}','${l.id}')">Beëindigen</button>`:st==='paused'?`<button class="tiny-action" onclick="event.stopPropagation();resumePackage('${c.id}','${l.id}')">Hervatten</button><button class="tiny-action danger-text" onclick="event.stopPropagation();endPackage('${c.id}','${l.id}')">Beëindigen</button>`:`<button class="tiny-action" onclick="event.stopPropagation();reactivatePackage('${c.id}','${l.id}')">Heractiveren</button>`}</div></div>`}).join('')}
function taskRow(c,t){return `<div class="task-row ${t.status==='done'?'done':''}"><button class="task-check" onclick="toggleTask('${c.id}','${t.id}')">${t.status==='done'?'✓':''}</button><span class="task-name">${esc(t.title)}</span><span class="task-date">${fmtDate(t.date)}</span><button class="outline" onclick="editTask('${c.id}','${t.id}')">•••</button></div>`}
function taskRowMini(t){return `<div class="listrow"><div class="avatar-square">${initials(t.client.company)}</div><div class="list-copy"><strong>${esc(t.task.title)}</strong><small>${esc(t.client.company)} · ${fmtDate(t.task.date)}</small></div></div>`}
function allTasks(filter='all'){return workspace().clients.flatMap(client=>(client.tasks||[]).map(task=>({client,task}))).filter(x=>filter==='all'||x.task.status===filter).sort((a,b)=>(a.task.date||'').localeCompare(b.task.date||''))}
function daysUntil(v){if(!v)return 9999;const now=new Date();now.setHours(12,0,0,0);return Math.ceil((new Date(v+'T12:00:00')-now)/86400000)}

function currentPeriod(c){const base=c.start?new Date(c.start):new Date(),now=new Date('2026-09-02T12:00:00');if((c.cycle||'calendar')==='client'){let s=new Date(now.getFullYear(),now.getMonth(),base.getDate());if(s>now)s=new Date(now.getFullYear(),now.getMonth()-1,base.getDate());const e=new Date(s.getFullYear(),s.getMonth()+1,s.getDate()-1);return{start:s.toISOString().slice(0,10),end:e.toISOString().slice(0,10)}}const s=new Date(now.getFullYear(),now.getMonth(),1),e=new Date(now.getFullYear(),now.getMonth()+1,0);return{start:s.toISOString().slice(0,10),end:e.toISOString().slice(0,10)}}
function onboardingChecklist(c){const o=c.onboarding||{};return[['contract','Contract rond'],['payment','Eerste betaling ontvangen'],['briefing','Briefing ontvangen'],['socials','Toegang socials'],['brand','Huisstijl ontvangen'],['start','Startdatum bevestigd']].map(([key,label])=>({key,label,done:!!o[key]}))}
function toggleOnboarding(id,key){const c=workspace().clients.find(x=>x.id===id);if(!c)return;c.onboarding=c.onboarding||{};c.onboarding[key]=!c.onboarding[key];if(c.status==='Onboarding'&&onboardingChecklist(c).every(x=>x.done))c.status='Actief';saveData('Onboarding bijgewerkt');render()}
function toggleAccess(id,key){const c=workspace().clients.find(x=>x.id===id);if(!c)return;c.access=c.access||{};c.access[key]=!c.access[key];saveData('Toegang bijgewerkt');render()}
function lynqAttention(c){const ns=notifications().filter(n=>n.clientId===c.id&&n.priority!=='info');const p=currentPeriod(c),days=daysUntil(p.end),open=Math.max(0,postsFor(c)-Number(c.postsDone||0)),notScheduled=Math.max(0,postsFor(c)-Number(c.postsScheduled||0));if(days<=7&&open>0)ns.unshift({title:`${open} posts nog open`,sub:`Periode eindigt over ${days} dagen`,priority:'attention'});if(notScheduled>0)ns.push({title:`${notScheduled} posts nog niet ingepland`,sub:'Deze maand',priority:'info'});return ns}

function ensureWorkspaceExtras(){let changed=false;Object.values(data).forEach(w=>{w.apps=w.apps||[{id:'app-notion',name:'Notion',url:'https://www.notion.so',icon:'N'},{id:'app-canva',name:'Canva',url:'https://www.canva.com',icon:'C'}];w.bankSettings=w.bankSettings||{mode:'manual',connected:false};(w.clients||[]).forEach(c=>{c.payments=c.payments||[];c.onboarding=c.onboarding||{};c.access=c.access||{};c.contentPlan=c.contentPlan||[];(c.serviceLinks||[]).forEach(l=>{if(!l.id){l.id=uid('sl');changed=true}l.pauseHistory=l.pauseHistory||[]})})});if(changed)saveData('Koppelingen bijgewerkt')}
ensureWorkspaceExtras();
setTimeout(scanImportantNotifications,0);
function seedContentPlanning(){if(data.lynq.contentPlanningVersion===1)return;const samples={l1:[['2026-09-02','19:00','Klant video','Mijlpaal vieren','scheduled','interview','Instagram'],['2026-09-04','19:00','Praatvideo','Veelgemaakte fout binnen het vak','scheduled','talk','Instagram'],['2026-09-07','','Reel','Behind the scenes van het proces','review','reel','Instagram']],l2:[['2026-09-03','16:30','Interview','Doelgroep: veilig en persoonlijk werken','scheduled','talk','Instagram'],['2026-09-09','16:00','Praatvideo','Missie en visie van de founder','scheduled','talk','TikTok']],l3:[['2026-09-10','','Reel','Eerste kennismaking met het merk','draft','reel','Instagram']]};for(const c of data.lynq.clients){if(!(c.contentPlan||[]).length&&(samples[c.id]||[]).length)c.contentPlan=samples[c.id].map(x=>({id:uid('cp'),date:x[0],time:x[1],concept:x[2],description:x[3],status:x[4],type:x[5],platform:x[6],asset:'',notes:''}))}data.lynq.contentPlanningVersion=1;saveData('Contentplanner toegevoegd')}
seedContentPlanning();
function financeItemsForClient(c){if(state.workspace==='sheling')return(c.installments||[]).map(i=>({id:i.id,amount:Number(i.amount||0),due:i.due,status:i.status||'open',label:`Termijn ${i.nr||''}`.trim(),paidDate:i.paidDate||''}));return(c.payments||[]).map(i=>({id:i.id,amount:Number(i.amount||0),due:i.due,status:i.status||'open',label:i.label||'Betaling',paidDate:i.paidDate||''}))}
function financeStatus(i){if(i.status==='paid')return'paid';const d=daysUntil(i.due);if(d<0)return'overdue';if(d===0)return'today';return'open'}
function allFinanceItems(){const rows=[];workspace().clients.forEach(c=>financeItemsForClient(c).forEach(item=>rows.push({c,item,status:financeStatus(item)})));return rows}
function financeSummaryForClient(c){const items=financeItemsForClient(c),paid=items.filter(x=>financeStatus(x)==='paid').reduce((a,x)=>a+x.amount,0),open=items.filter(x=>financeStatus(x)!=='paid').reduce((a,x)=>a+x.amount,0),overdue=items.filter(x=>financeStatus(x)==='overdue').reduce((a,x)=>a+x.amount,0);return{items,paid,open,overdue,total:paid+open}}
function addClientPayment(id){const c=workspace().clients.find(x=>x.id===id);if(!c)return;const l=activeLink(c),s=serviceById(l?.serviceId),amount=prompt('Bedrag:',String(l?.rate||s?.price||''));if(amount===null||amount==='')return;const due=prompt('Betaaldatum / vervaldatum (YYYY-MM-DD):','');if(!due)return;const label=prompt('Omschrijving:',state.workspace==='sheling'?'Termijnbetaling':'Maandbetaling')||'Betaling';if(state.workspace==='sheling'){c.installments=c.installments||[];const nr=(c.installments.length?Math.max(...c.installments.map(x=>Number(x.nr)||0)):0)+1;c.installments.push({id:uid('i'),nr,amount:Number(amount),due,status:'open'})}else{c.payments=c.payments||[];c.payments.push({id:uid('pay'),label,amount:Number(amount),due,status:'open'})}saveData('Betaling toegevoegd');toast('Betaling toegevoegd');render()}
function markClientPayment(id,pid){const c=workspace().clients.find(x=>x.id===id);if(!c)return;const list=state.workspace==='sheling'?(c.installments||[]):(c.payments||[]),i=list.find(x=>x.id===pid);if(!i)return;i.status='paid';i.paidDate=new Date().toISOString().slice(0,10);saveData('Betaling bijgewerkt');toast('Gemarkeerd als betaald');render()}
function reopenClientPayment(id,pid){const c=workspace().clients.find(x=>x.id===id);if(!c)return;const list=state.workspace==='sheling'?(c.installments||[]):(c.payments||[]),i=list.find(x=>x.id===pid);if(!i)return;i.status='open';i.paidDate='';saveData('Betaling heropend');render()}
function openApps(){const apps=workspace().apps||[];openModal(`<div class="drawer-head"><div><div class="drawer-title">Apps</div><div class="page-sub">Open je vaste tools of voeg zelf een app toe.</div></div><button class="closebtn" onclick="closeModal()">×</button></div><div class="apps-launch-grid">${apps.map(a=>`<div class="app-launch-card"><a href="${esc(a.url)}" target="_blank"><span class="app-launch-icon real-app-icon">${appIconSrc(a)?`<img src="${appIconSrc(a)}" alt="${esc(a.name)}">`:`<b>${esc(a.name?.[0]||'A')}</b>`}</span><strong>${esc(a.name)}</strong><small>${esc(appDomain(a.url))}</small></a><button onclick="editCustomApp('${a.id}')">•••</button></div>`).join('')||'<div class="empty">Nog geen apps toegevoegd.</div>'}</div><div class="drawer-actions"><button class="outline" onclick="closeModal()">Sluiten</button><button class="primary" onclick="addCustomApp()">+ App toevoegen</button></div>`)}
function addCustomApp(){const name=prompt('Naam van de app:','');if(!name)return;const url=prompt('Link naar de app:','https://');if(!url)return;const icon=(prompt('Letter/icoon:',name[0].toUpperCase())||name[0]).slice(0,3);workspace().apps.push({id:uid('app'),name,url,icon});saveData('App toegevoegd');openApps()}
function editCustomApp(id){const a=workspace().apps.find(x=>x.id===id);if(!a)return;const name=prompt('Naam:',a.name);if(name===null)return;const url=prompt('Link:',a.url);if(url===null)return;const action=prompt('Typ VERWIJDEREN om te verwijderen, anders leeg laten:','');if(action==='VERWIJDEREN'){workspace().apps=workspace().apps.filter(x=>x.id!==id);saveData('App verwijderd');openApps();return}a.name=name||a.name;a.url=url||a.url;saveData('App bijgewerkt');openApps()}
function notifications(){return workspace().clients.flatMap(c=>{const arr=[];const end=daysUntil(c.end),resume=daysUntil(c.resume);if(state.workspace==='lynq'){
  const open=Math.max(0,postsFor(c)-(c.postsDone||0));if(open>0)arr.push({clientId:c.id,title:`${open} posts nog open voor ${c.company}`,sub:`${c.postsDone||0} van ${postsFor(c)} online deze maand`,priority:open>=Math.ceil(postsFor(c)*.5)?'attention':'info'});
  if(c.end&&end>=0&&end<=30)arr.push({clientId:c.id,title:`Samenwerking ${c.company} eindigt ${end===0?'vandaag':`over ${end} dagen`}`,sub:fmtDate(c.end),priority:end<=7?'urgent':'attention'});
}else{
  if(c.end&&end>=0&&end<=30)arr.push({clientId:c.id,title:`Traject ${c.contact} eindigt ${end===0?'vandaag':`over ${end} dagen`}`,sub:fmtDate(c.end),priority:end<=7?'urgent':'attention'});
  if(c.status==='Gepauzeerd'&&c.resume&&resume>=0&&resume<=30)arr.push({clientId:c.id,title:`${c.contact} hervat ${resume===0?'vandaag':resume===1?'morgen':`over ${resume} dagen`}`,sub:fmtDate(c.resume),priority:resume<=1?'urgent':'attention'});
  (c.installments||[]).filter(i=>i.status!=='paid').forEach(i=>{const d=daysUntil(i.due);if(d<0)arr.push({clientId:c.id,page:'installments',title:`Betaling ${money(i.amount)} van ${c.contact} is achterstallig`,sub:`Vervaldatum ${fmtDate(i.due)}`,priority:'urgent'});else if(d<=7)arr.push({clientId:c.id,page:'installments',title:`Termijn ${money(i.amount)} voor ${c.contact}`,sub:d===0?'Vervalt vandaag':`Vervalt over ${d} dagen`,priority:d<=1?'urgent':'attention'})});
}return arr}).sort((a,b)=>({urgent:0,attention:1,info:2}[a.priority]-({urgent:0,attention:1,info:2}[b.priority])))}
function csvDetectDelimiter(line=''){const choices=[',',';','\t'];let best=',',count=-1;for(const d of choices){let c=0,q=false;for(let i=0;i<line.length;i++){if(line[i]==='"')q=!q;else if(!q&&line[i]===d)c++}if(c>count){count=c;best=d}}return best}
function parseCSV(text=''){text=String(text||'').replace(/^\uFEFF/,'');const first=(text.split(/\r?\n/).find(x=>x.trim())||'');const delimiter=csvDetectDelimiter(first);const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const ch=text[i],next=text[i+1];if(ch==='"'){if(q&&next==='"'){cell+='"';i++}else q=!q}else if(ch===delimiter&&!q){row.push(cell.trim());cell=''}else if((ch==='\n'||ch==='\r')&&!q){if(ch==='\r'&&next==='\n')i++;row.push(cell.trim());cell='';if(row.some(v=>v!==''))rows.push(row);row=[]}else cell+=ch}row.push(cell.trim());if(row.some(v=>v!==''))rows.push(row);if(!rows.length)return{headers:[],rows:[]};const headers=rows.shift().map((h,i)=>h||`Kolom ${i+1}`);return{headers,rows:rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]||''])))} }
function normalizeHeader(v=''){return String(v).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'')}
const CLIENT_IMPORT_FIELDS=[
  ['company','Bedrijf / klantnaam',['naam','klant','klantnaam','bedrijf','bedrijfsnaam','company','name']],
  ['contact','Contactpersoon',['contact','contactpersoon','persoon','contactname']],
  ['email','E-mail',['email','emailadres','emailaddress','mail']],
  ['phone','Telefoon',['telefoon','telefoonnummer','phone','mobiel','mobile']],
  ['status','Status',['status','klantstatus']],
  ['start','Startdatum',['start','startdatum','begindatum','startdate']],
  ['end','Einddatum',['eind','einddatum','end','enddate']],
  ['website','Website',['website','site','url']],
  ['kvk','KVK',['kvk','kvknummer','chamberofcommerce']],
  ['address','Adres',['adres','address']],
  ['notion','Notion-link',['notion','notionlink','notionurl']],
  ['postsPerMonth','Posts per maand',['postspermaand','postspermonth','postspm','aantalposts']],
  ['service','Pakket / traject',['pakket','traject','dienst','service','package']],
  ['rate','Tarief',['tarief','prijs','rate','price','bedrag']]
];
function bestImportHeader(headers,aliases){const norms=headers.map(h=>[h,normalizeHeader(h)]);for(const alias of aliases){const n=normalizeHeader(alias),exact=norms.find(([,v])=>v===n);if(exact)return exact[0]}for(const alias of aliases){const n=normalizeHeader(alias),partial=norms.find(([,v])=>v.includes(n)||n.includes(v));if(partial)return partial[0]}return''}
function openClientImport(){openModal(`<div class="drawer-head"><div><div class="drawer-title">Klanten importeren</div><div class="page-sub">${state.workspace==='lynq'?'LYNQ Agency':'ShelingCynthia'} · ook geschikt voor een CSV-export uit Notion</div></div><button class="closebtn" onclick="closeModal()">×</button></div><div class="import-intro"><strong>Van Notion naar deze software</strong><p>Exporteer je klantdatabase in Notion als CSV en upload dat bestand hier. Je kunt straks controleren welke kolom waar terechtkomt voordat er iets wordt geïmporteerd.</p></div><label class="client-import-drop" for="clientCsvFile"><span>⇧</span><strong>Kies CSV-bestand</strong><small>CSV uit Notion, Excel of Google Sheets</small><input id="clientCsvFile" type="file" accept=".csv,text/csv" hidden></label><div id="clientImportStage"></div><div class="drawer-actions"><button class="outline" onclick="closeModal()">Sluiten</button></div>`);$('#clientCsvFile').onchange=e=>e.target.files[0]&&readClientCSV(e.target.files[0])}
function readClientCSV(file){const r=new FileReader();r.onload=()=>{const parsed=parseCSV(r.result);if(!parsed.headers.length||!parsed.rows.length){toast('Geen klanten gevonden in dit CSV-bestand');return}window.__clientImport=parsed;renderClientImportMapping(parsed)};r.onerror=()=>toast('CSV kon niet worden gelezen');r.readAsText(file)}
function renderClientImportMapping(parsed){const opts=h=>`<option value="">Niet importeren</option>${parsed.headers.map(x=>`<option value="${esc(x)}" ${x===h?'selected':''}>${esc(x)}</option>`).join('')}`;const selects=CLIENT_IMPORT_FIELDS.map(([field,label,aliases])=>{const best=bestImportHeader(parsed.headers,aliases);return `<label><span>${label}</span><select data-import-field="${field}">${opts(best)}</select></label>`}).join('');const preview=parsed.rows.slice(0,5).map(r=>`<tr>${parsed.headers.slice(0,5).map(h=>`<td>${esc(r[h]||'—')}</td>`).join('')}</tr>`).join('');$('#clientImportStage').innerHTML=`<div class="import-summary"><strong>${parsed.rows.length} klant${parsed.rows.length===1?'':'en'} gevonden</strong><span>Controleer de kolommen hieronder.</span></div><div class="import-mapping-grid">${selects}</div><div class="import-preview-wrap"><table class="table"><thead><tr>${parsed.headers.slice(0,5).map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${preview}</tbody></table></div><div class="import-options"><label><input id="skipDuplicates" type="checkbox" checked> Dubbele klanten op basis van e-mail overslaan</label></div><div class="drawer-actions inline-import-actions"><button class="outline" onclick="openClientImport()">Ander bestand</button><button class="primary wine-btn" onclick="confirmClientImport()">${parsed.rows.length} klanten importeren</button></div>`}
function importDate(v=''){v=String(v||'').trim();if(!v)return'';if(/^\d{4}-\d{2}-\d{2}$/.test(v))return v;const m=v.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})$/);if(m){let y=m[3];if(y.length===2)y='20'+y;return `${y}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`}const d=new Date(v);return Number.isNaN(d.getTime())?'':d.toISOString().slice(0,10)}
function confirmClientImport(){const parsed=window.__clientImport;if(!parsed)return;const mapping={};$$('[data-import-field]').forEach(el=>mapping[el.dataset.importField]=el.value);if(!mapping.company&&!mapping.contact){toast('Koppel minimaal een klantnaam of contactpersoon');return}const isL=state.workspace==='lynq',skip=$('#skipDuplicates')?.checked!==false,existing=new Set(workspace().clients.map(c=>String(c.email||'').trim().toLowerCase()).filter(Boolean));let added=0,skipped=0;for(const row of parsed.rows){const get=k=>mapping[k]?String(row[mapping[k]]||'').trim():'';const email=get('email').toLowerCase();if(skip&&email&&existing.has(email)){skipped++;continue}const company=get('company')||get('contact')||'Naamloos';const contact=get('contact')||company;const serviceName=get('service');let serviceLink=[];if(serviceName){const norm=normalizeHeader(serviceName);const svc=workspace().services.find(s=>normalizeHeader(s.name)===norm||normalizeHeader(s.name).includes(norm)||norm.includes(normalizeHeader(s.name)));if(svc)serviceLink=[{id:uid('sl'),serviceId:svc.id,rate:Number(String(get('rate')).replace(/[^0-9,.-]/g,'').replace(',','.'))||Number(svc.price||0),status:'active',started:importDate(get('start'))||new Date().toISOString().slice(0,10)}]}
const c={id:uid(isL?'l':'s'),company,contact,email:get('email'),phone:get('phone'),status:get('status')||(isL?'Onboarding':'Actief'),start:importDate(get('start')),end:importDate(get('end')),resume:'',pause:'',website:get('website'),kvk:get('kvk'),address:get('address'),notion:get('notion'),serviceLinks:serviceLink,notes:[],tasks:[],appointments:[],installments:[],payments:[],contentPlan:[],postsDone:0,postsScheduled:0,postsPerMonth:Number(get('postsPerMonth'))||0,cycle:'calendar',onboarding:{},access:{}};workspace().clients.push(c);if(email)existing.add(email);added++}saveData(`${added} klanten geïmporteerd`);closeModal();toast(`${added} geïmporteerd${skipped?` · ${skipped} dubbel overgeslagen`:''}`);go('clients')}
